] || 'request';\\nconst company = e.companyName || 'our team';\\n\\nconst ackText = [\\n  `Hi ${firstName},`,\\n  '',\\n  `Thank you for contacting ${company}. We have received your ${what} (reference: ${e.jiraKey}) and passed it to the right team.`,\\n  `You can expect an update within ${RESPONSE_TIME[e.priority] || '2 business days'}. Just reply to this email if you have anything to add.`,\\n  '',\\n  'Kind regards,',\\n  `${company} ${e.ackSignature || ''}`.trim(),\\n].join('\\\\n');\\nconst ackHtml = ackText.split('\\\\n').map(l => `<p style=\\"margin:0\\">${l || '&nbsp;'}</p>`).join('');\\n\\nreturn { json: { ...e, ackMode: mode, ackSkipReason: skip, ackText, ackHtml,\\n  ackRoute: skip ? 'skip' : (e.source === 'Outlook' ? 'outlook' : (mode === 'send' ? 'gmail-send' : 'gmail-draft')) } };"}, "typeVersion": 2}, {"id": "ad1adcf4-d01d-4fd0-8736-5f9878ac6bdd", "name": "Route by Reply Channel", "type": "n8n-nodes-base.switch", "position": [-2144, 5792], "parameters": {"rules": {"values": [{"outputKey": "Gmail send", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "4c142b9f-7a05-4c7a-809a-1e355e7e8705", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.ackRoute }}", "rightValue": "gmail-send"}]}, "renameOutput": true}, {"outputKey": "Gmail draft", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "8f69795d-0bd4-4912-8ad4-e0cb3c35e2d5", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.ackRoute }}", "rightValue": "gmail-draft"}]}, "renameOutput": true}, {"outputKey": "Outlook", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "43f278bf-677b-4573-b2b4-f5da53c450ab", "operator": {"type": "string", "operatio