4a466aaf-8d87-4416-96b3-dd334281f4d8	4fFRyTELz6JN10ON	import	2026-10-03 17:48:40.356+00	2026-10-03 17:48:40.356+00	[{"id": "0d9d00cf-bb7c-4426-9aaf-30378275dd1f", "name": "Angebote \\u00fcberwachen", "type": "n8n-nodes-base.googleSheetsTrigger", "position": [784, 304], "parameters": {"options": {}, "pollTimes": {"item": [{"mode": "everyMinute"}]}, "sheetName": {"__rl": true, "mode": "list", "value": "gid=0", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/18HTzdkvuVmXZbiT--jIjdJ8ykB7-5W2qNxpyMMVqdUg/edit#gid=0", "cachedResultName": "Tabellenblatt1"}, "documentId": {"__rl": true, "mode": "list", "value": "18HTzdkvuVmXZbiT--jIjdJ8ykB7-5W2qNxpyMMVqdUg", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/18HTzdkvuVmXZbiT--jIjdJ8ykB7-5W2qNxpyMMVqdUg/edit?usp=drivesdk", "cachedResultName": "FLOW AI Angebote"}}, "credentials": {"googleSheetsTriggerOAuth2Api": {"id": "b0266b0afd1844fc", "name": "Dummy googleSheetsTriggerOAuth2Api"}}, "typeVersion": 1}, {"id": "9d2716c4-962e-4b70-8e92-9b7fbbff69e0", "name": "Freigabe pr\\u00fcfen", "type": "n8n-nodes-base.if", "position": [1008, 304], "parameters": {"options": {}, "conditions": {"options": {"version": 3, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "8d943a68-c785-49a9-bbaf-be6b77f900cf", "operator": {"name": "filter.operator.equals", "type": "string", "operation": "equals"}, "leftValue": "={{ $json.Status }}", "rightValue": "FREIGEGEBEN"}]}}, "typeVersion": 2.3}, {"id": "7440e063-02ef-45db-9341-0577c0d23567", "name": "Angebotsdaten berechnen", "type": "n8n-nodes-base.code", "position": [1232, 304], "parameters": {"mode": "runOnceForEachItem", "jsCode": "const daten = { ...$json };\\n\\nconst pflichtfelder = [\\n  'Kundenname',\\n  'Kunden_E-Mail',\\n  'Leistungsbeschreibung',\\n  'Gesamt_Netto'\\n];\\n\\nconst fehlendeFelder = pflichtfelder.filter(\\n  feld =>\\n    daten[feld] === undefined ||\\n    daten[feld] === null ||\\n    String(daten[feld]).trim() === ''\\n);\\n\\nif (fehlendeFelder.length > 0) {\\n  throw new Error(\\n    `Folgende Pflichtfelder fehlen: ${fehlendeFelder.join(', ')}`\\n  );\\n}\\n\\nfunction zahlEinlesen(wert, standardwert = 0) {\\n  if (wert === undefined || wert === null || wert === '') {\\n    return standardwert;\\n  }\\n\\n  if (typeof wert === 'number') {\\n    return wert;\\n  }\\n\\n  let text = String(wert)\\n    .trim()\\n    .replace(/\\\\s/g, '')\\n    .replace(/\\u20ac/g, '');\\n\\n  if (text.includes(',') && text.includes('.')) {\\n    text = text.replace(/\\\\./g, '').replace(',', '.');\\n  } else if (text.includes(',')) {\\n    text = text.replace(',', '.');\\n  }\\n\\n  const zahl = Number(text);\\n\\n  if (!Number.isFinite(zahl)) {\\n    throw new Error(`Ung\\u00fcltiger Zahlenwert: ${wert}`);\\n  }\\n\\n  return zahl;\\n}\\n\\nfunction deutschesDatum(datum) {\\n  return new Intl.DateTimeFormat('de-DE', {\\n    timeZone: 'Europe/Berlin',\\n    day: '2-digit',\\n    month: '2-digit',\\n    year: 'numeric'\\n  }).format(datum);\\n}\\n\\nfunction datumEinlesen(wert, standardDatum) {\\n  if (\\n    wert === undefined ||\\n    wert === null ||\\n    String(wert).trim() === ''\\n  ) {\\n    return deutschesDatum(standardDatum);\\n  }\\n\\n  if (wert instanceof Date && !Number.isNaN(wert.getTime())) {\\n    return deutschesDatum(wert);\\n  }\\n\\n  const text = String(wert).trim();\\n  const seriennummer = Number(text.replace(',', '.'));\\n\\n  // Google Sheets speichert Datumswerte intern als Seriennummern.\\n  if (\\n    Number.isFinite(seriennummer) &&\\n    seriennummer >= 20000 &&\\n    seriennummer <= 80000\\n  ) {\\n    const datum = new Date(\\n      Date.UTC(1899, 11, 30) +\\n      Math.floor(seriennummer) * 86400000\\n    );\\n\\n    return deutschesDatum(datum);\\n  }\\n\\n  const deutschesFormat =\\n    text.match(/^(\\\\d{1,2})\\\\.(\\\\d{1,2})\\\\.(\\\\d{4})$/);\\n\\n  if (deutschesFormat) {\\n    const [, tag, monat, jahr] = deutschesFormat;\\n\\n    return [\\n      tag.padStart(2, '0'),\\n      monat.padStart(2, '0'),\\n      jahr\\n    ].join('.');\\n  }\\n\\n  const isoFormat =\\n    text.match(/^(\\\\d{4})-(\\\\d{2})-(\\\\d{2})/);\\n\\n  if (isoFormat) {\\n    const [, jahr, monat, tag] = isoFormat;\\n    return `${tag}.${monat}.${jahr}`;\\n  }\\n\\n  const datum = new Date(text);\\n\\n  if (!Number.isNaN(datum.getTime())) {\\n    return deutschesDatum(datum);\\n  }\\n\\n  throw new Error(`Ung\\u00fcltiger Datumswert: ${wert}`);\\n}\\n\\nconst jetzt = new Date();\\nconst nettobetrag = zahlEinlesen(daten.Gesamt_Netto);\\nconst mwstProzent = zahlEinlesen(daten.MwSt_Prozent, 19);\\nconst bruttobetrag = Number(\\n  (nettobetrag * (1 + mwstProzent / 100)).toFixed(2)\\n);\\n\\nconst jahr = new Intl.DateTimeFormat('de-DE', {\\n  timeZone: 'Europe/Berlin',\\n  year: 'numeric'\\n}).format(jetzt);\\n\\nconst kennung =\\n  daten.row_number !== undefined\\n    ? String(daten.row_number).padStart(4, '0')\\n    : String(Date.now()).slice(-6);\\n\\nconst gueltigBis = new Date(jetzt);\\ngueltigBis.setDate(gueltigBis.getDate() + 14);\\n\\ndaten.Angebotsnummer =\\n  daten.Angebotsnummer || `ANG-${jahr}-${kennung}`;\\n\\ndaten.Angebotsdatum =\\n  datumEinlesen(daten.Angebotsdatum, jetzt);\\n\\ndaten.Gesamt_Netto = nettobetrag;\\ndaten.MwSt_Prozent = mwstProzent;\\ndaten.Gesamt_Brutto = bruttobetrag;\\n\\ndaten.Gueltig_bis =\\n  datumEinlesen(daten.Gueltig_bis, gueltigBis);\\n\\ndaten.Zahlungsbedingungen =\\n  daten.Zahlungsbedingungen ||\\n  'Zahlbar innerhalb von 14 Tagen ohne Abzug.';\\n\\ndelete daten.row_number;\\ndelete daten.change_type;\\n\\nreturn {\\n  json: daten\\n};"}, "typeVersion": 2}, {"id": "abcd3f40-4248-40ce-943a-db0f105c4310", "name": "Angebotstext erstellen", "type": "@n8n/n8n-nodes-langchain.agent", "position": [1440, 304], "parameters": {"text": "=Du erstellst einen professionellen Angebotsentwurf f\\u00fcr einen deutschen Handwerksbetrieb.\\n\\nVerwende ausschlie\\u00dflich die nachfolgenden Daten. Erfinde keine zus\\u00e4tzlichen Leistungen, Mengen, Preise, Rabatte, Termine, Zusagen oder Gesch\\u00e4ftsbedingungen. Berechne keine Betr\\u00e4ge neu und \\u00fcbernimm die angegebenen Preise exakt.\\n\\nANGEBOTSDATEN\\n\\nAngebotsnummer: {{ $json.Angebotsnummer }}\\nAngebotsdatum: {{ $json.Angebotsdatum }}\\n\\nKundenname: {{ $json.Kundenname }}\\nKunden-E-Mail: {{ $json[\\"Kunden_E-Mail\\"] }}\\nStra\\u00dfe und Hausnummer: {{ $json.Strasse_Hausnummer }}\\nPLZ: {{ $json.PLZ }}\\nOrt: {{ $json.Ort }}\\n\\nProjektart: {{ $json.Projektart }}\\nLeistungsbeschreibung: {{ $json.Leistungsbeschreibung }}\\n\\nGesamt netto: {{ $json.Gesamt_Netto }} EUR\\nMehrwertsteuer: {{ $json.MwSt_Prozent }} Prozent\\nGesamt brutto: {{ $json.Gesamt_Brutto }} EUR\\n\\nG\\u00fcltig bis: {{ $json.Gueltig_bis }}\\nZahlungsbedingungen: {{ $json.Zahlungsbedingungen }}\\n\\nERSTELLE DEN ANGEBOTSTEXT MIT DIESER STRUKTUR\\n\\n1. \\u00dcberschrift \\u201eAngebot\\u201c\\n2. Angebotsnummer und Angebotsdatum\\n3. Kundenanschrift\\n4. Betreff passend zur Projektart\\n5. Pers\\u00f6nliche und professionelle Anrede\\n6. Kurze Einleitung\\n7. \\u00dcberschrift \\u201eLeistungsumfang\\u201c\\n8. Vollst\\u00e4ndige Leistungsbeschreibung\\n9. \\u00dcbersicht mit Nettobetrag, Mehrwertsteuersatz und Bruttobetrag\\n10. G\\u00fcltigkeitsdauer und Zahlungsbedingungen\\n11. Freundlicher Abschlusstext\\n\\nREGELN\\n\\n- Schreibe auf Deutsch.\\n- Formuliere professionell, freundlich und verst\\u00e4ndlich.\\n- \\u00dcbernimm alle Betr\\u00e4ge exakt.\\n- Berechne keine eigenen Preise.\\n- Erg\\u00e4nze keine nicht genannten Leistungen.\\n- Leere optionale Angaben werden weggelassen.\\n- Antworte ausschlie\\u00dflich mit dem fertigen Angebotstext.\\n- Verwende keine Markdown-Codebl\\u00f6cke und keine Erkl\\u00e4rungen.\\n\\nFormatiere alle Geldbetr\\u00e4ge im deutschen Zahlenformat mit zwei Nachkommastellen und Eurozeichen, zum Beispiel: 1.250,00 \\u20ac.\\n\\nVerwende keine nummerierten Abschnittsbezeichnungen und keine Formulierungen wie \\u201e1. \\u00dcberschrift\\u201c. Beginne direkt mit \\u201eAngebot\\u201c.\\n\\nSchreibe nach \\u201eMit freundlichen Gr\\u00fc\\u00dfen\\u201c keinen erfundenen Firmennamen oder Ansprechpartner.", "options": {}, "promptType": "define"}, "typeVersion": 3.1}, {"id": "8c792b7d-acae-4433-bd62-d6ed7d434afb", "name": "OpenAI Chat Model", "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi", "position": [1440, 512], "parameters": {"model": {"__rl": true, "mode": "list", "value": "gpt-5-mini"}, "options": {}, "builtInTools": {}}, "credentials": {"openAiApi": {"id": "d83021c6ea6c47ee", "name": "Dummy openAiApi"}}, "typeVersion": 1.3}, {"id": "c04d62d7-36ce-4639-8375-fb57a76d58aa", "name": "Angebot zusammenfuehren", "type": "n8n-nodes-base.code", "position": [1808, 304], "parameters": {"mode": "runOnceForEachItem", "jsCode": "const basisdaten =\\n  $('Angebotsdaten berechnen').item.json;\\n\\nconst angebotstext = String(\\n  $json.output || ''\\n).trim();\\n\\nif (!angebotstext) {\\n  throw new Error(\\n    'Der KI-Agent hat keinen Angebotstext erstellt.'\\n  );\\n}\\n\\nreturn {\\n  json: {\\n    ...basisdaten,\\n    Angebotstext: angebotstext,\\n    Status: 'ERSTELLT'\\n  }\\n};"}, "typeVersion": 2}, {"id": "69f7f3de-1bcf-4704-b794-f28942d69ade", "name": "Angebot in Tabelle aktualisieren", "type": "n8n-nodes-base.googleSheets", "position": [2032, 304], "parameters": {"columns": {"value": {}, "schema": [{"id": "Angebotsnummer", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Angebotsnummer", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Angebotsdatum", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Angebotsdatum", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Kundenname", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Kundenname", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Kunden_E-Mail", 