tatus:\\n      'ENTWURF',\\n\\n    Gmail_Thread_ID:\\n      emailDaten.Gmail_Thread_ID || '',\\n\\n    Haendlerangebot_Link: ''\\n  }\\n};"}, "typeVersion": 2}, {"id": "537bf7cc-16a3-42d3-96b5-6787347c1dca", "name": "Preisanfrage in Tabelle speichern", "type": "n8n-nodes-base.googleSheets", "position": [3648, 1760], "parameters": {"columns": {"value": {}, "schema": [{"id": "Preisanfrage_ID", "type": "string", "display": true, "required": false, "displayName": "Preisanfrage_ID", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Angebotsnummer", "type": "string", "display": true, "required": false, "displayName": "Angebotsnummer", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Anfragedatum", "type": "string", "display": true, "required": false, "displayName": "Anfragedatum", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Grosshaendler", "type": "string", "display": true, "required": false, "displayName": "Grosshaendler", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Grosshaendler_E-Mail", "type": "string", "display": true, "required": false, "displayName": "Grosshaendler_E-Mail", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Kundenname", "type": "string", "display": true, "required": false, "displayName": "Kundenname", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Projektart", "type": "string", "display": true, "required": false, "displayName": "Projektart", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "LV_Leistungen", "type": "string", "display": true, "required": false, "displayName": "LV_Leistungen", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "LV_Materialien", "type": "string", "display": true, "required": false, "displayName": "LV_Materialien", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "LV_Mengen", "type": "string", "display": true, "required": false, "displayName": "LV_Mengen", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Preisanfrage_Text", "ty