alue": "gid=0", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/1_VVpkIvpYQigw5q0KmPXUAC2aV2rk1nRQLQZ7YK2KwY/edit#gid=0", "cachedResultName": "Sheet2"}, "documentId": {"__rl": true, "mode": "list", "value": "1_VVpkIvpYQigw5q0KmPXUAC2aV2rk1nRQLQZ7YK2KwY", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/1_VVpkIvpYQigw5q0KmPXUAC2aV2rk1nRQLQZ7YK2KwY/edit?usp=drivesdk", "cachedResultName": "Website Moniter"}}, "credentials": {"googleSheetsOAuth2Api": {"id": "cbc1b5f60f3e43a0", "name": "Dummy googleSheetsOAuth2Api"}}, "executeOnce": false, "typeVersion": 4.6, "alwaysOutputData": true}, {"id": "57f054ee-8f40-45a9-9da9-3befd1ac489c", "name": "Update Uptime and Total Downtime", "type": "n8n-nodes-base.googleSheets", "position": [420, 1800], "parameters": {"columns": {"value": {"Up Time": "={{ new Date().toLocaleTimeString('en-GB', { hour12: false }) }}", "row_number": "={{ $json.row_number }}", "Website URL": "={{ $json['Website URL'] }}", "Total downtime": "={{(() => {\\n  const downTimeStr = $input.first().json['Down Time'];\\n\\n  // Get current time in HH:MM:SS format\\n  const now = new Date();\\n  const upTimeStr = now.toLocaleTimeString('en-GB', { hour12: false });\\n\\n  function parseTime(timeStr) {\\n    const [h, m, s] = timeStr.split(\\":\\").map(Number);\\n    const date = new Date();\\n    date.setHours(h, m, s, 0);\\n    return date;\\n  }\\n\\n  const downTime = parseTime(downTimeStr);\\n  const upTime = parseTime(upTimeStr);\\n\\n  // Handle overnight scenario\\n  if (upTime < downTime) {\\n    upTime.setDate(upTime.getDate() + 1);\\n  }\\n\\n  const diffMs = upTime - downTime;\\n  const totalMinutes = Math.floor(diffMs / 60000);\\n  const hours = Math.floor(totalMinutes / 60);\\n  const minutes = totalMinutes % 60;\\n  const seconds = Math.floor((diffMs % 60000) / 1000);\\n\\n  return `${hours}h ${minutes}m ${seconds}s`;\\n})()}}"}, "schema": [{"id": "Website URL", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Website URL", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Down Time", "type": "string", "display": true, "removed": true, "required": false, "displayName": "Down Time", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Up Time", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Up Time", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Total downtime", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Total downtime", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "row_number", "type": "string", "display": true, "removed": false, "readOnly": true, "required": false, "displayName": "row_number", "defaultMatch": false, "canBeUsedToMatch": true}], "mappingMode": "defineBelow", "matchingColumns": ["row_number"], "attemptToConvertTypes": false, "convertFieldsToString": false}, "options": {}, "operation": "update", "sheetName": {"__rl": true, "mode": "list", "value": "gid=0", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/1_VVpkIvpYQigw5q0KmPXUAC2aV2rk1nRQLQZ7YK2KwY/edit#gid=0", "cachedResultName": "Sheet2"}, "documentId": {"__rl": true, "mode": "list", "value": "1_VVpkIvpYQigw5q0KmPXUAC2aV2rk1nRQLQZ7YK2KwY", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/1_VVpkIvpYQigw5q0KmPXUAC2aV2rk1nRQLQZ7YK2KwY/edit?usp=drivesdk", "cachedResultName": "Website Moniter"}}, "credentials": {"googleSheetsOAuth2Api": {"id": "cbc1b5f60f3e43a0", "name": "Dummy googleSheetsOAuth2Api"}}, "executeOnce": false, "typeVersion": 4.6, "alwaysOutputData": true}, {"id": "e6575156-1a32-429a-9ee7-deef3c4f863d", "name": "Find Existing Record", "type": "n8n-nodes-base.code", "position": [200, 2200], "parameters": {"jsCode": "let hasIncompleteRecord = false;\\n\\nfor (const item of $input.all()) {\\n  const url = item.json['Website URL']?.trim();\\n  const downTime = item.json['Down Time']?.trim();\\n  const upTime = item.json['Up Time']?.trim();\\n  const totalDowntime = item.json['Total downtime']?.trim();\\n\\n  if (url && downTime && (!upTime || !totalDowntime)) {\\n    hasIncompleteRecord = true;\\n  }\\n}\\n\\nreturn [\\n  {\\n    json: {\\n      status: hasIncompleteRecord ? \\"yes\\" : \\"no\\",\\n      websites: $input.first().json['Website URL']\\n    }\\n  }\\n];\\n"}, "typeVersion": 2}, {"id": "220717dd-659a-44af-98f8-3e03aa0021ea", "name": "Add Downtime Record", "type": "n8n-nodes-base.googleSheets", "position": [640, 2200], "parameters": {"columns": {"value": {"Down Time": "={{ new Date().toLocaleTimeString('en-GB', { hour12: false }) }}", "Website URL": "={{ $('Loop Over Items').item.json[\\"Website URL\\"] }}"}, "schema": [{"id": "Website URL", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Website URL", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Down Time", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Down Time", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Up Time", "type": "string", "display": true, "removed": true, "required": false, "displayName": "Up Time", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Total downtime", "type": "string", "display": true, "removed": true, "required": false, "displayName": "Total downtime", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "row_number", "type": "string", "display": true, "removed": false, "readOnly": true, "required": false, "displayName": "row_number", "defaultMatch": false, "canBeUsedToMatch": true}], "mappingMode": "defineBelow", "matchingColumns": ["Website URL"], "attemptToConvertTypes": false, "convertFieldsToString": false}, "options": {}, "operation": "append", "sheetName": {"__rl": true, "mode": "list", "value": "gid=0", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/1_VVpkIvpYQigw5q0KmPXUAC2aV2rk1nRQLQZ7YK2KwY/edit#gid=0", "cachedResultName": "Sheet2"}, "documentId": {"__rl": true, "mode": "li