ookId": "1000b40d-5dc5-4795-9dd2-8a23653c2b49", "parameters": {}, "typeVersion": 1.1}, {"id": "0853153e-33a3-44a8-ab22-c296b7aab892", "name": "Qdrant Vector Store", "type": "@n8n/n8n-nodes-langchain.vectorStoreQdrant", "position": [2380, 540], "parameters": {"mode": "insert", "options": {"collectionConfig": ""}, "qdrantCollection": {"__rl": true, "mode": "list", "value": "ocr_mistral_test", "cachedResultName": "ocr_mistral_test"}}, "credentials": {"qdrantApi": {"id": "cred_qdrant_1", "name": "Automata Qdrant API"}}, "typeVersion": 1.1}, {"id": "4123fa10-ec36-40cd-ad85-b8353479db28", "name": "Loop Over Items1", "type": "n8n-nodes-base.splitInBatches", "position": [540, -300], "parameters": {"options": {}}, "typeVersion": 3}, {"id": "16fadeb2-5612-421e-8da3-37bed966d966", "name": "Execute Workflow", "type": "n8n-nodes-base.executeWorkflow", "position": [1160, -280], "parameters": {"mode": "each", "options": {"waitForSubWorkflow": true}, "workflowId": {"__rl": true, "mode": "list", "value": "AdVUaHTE9Jk1KO72", "cachedResultName": "Mistral OCR_subworkflow"}, "workflowInputs": {"value": {}, "schema": [], "mappingMode": "defineBelow", "matchingColumns": [], "attemptToConvertTypes": false, "convertFieldsToString": true}}, "typeVersion": 1.2}, {"id": "0f61b1ab-45a3-4167-a4f1-baeca03109bd", "name": "When Executed by Another Workflow", "type": "n8n-nodes-base.executeWorkflowTrigger", "position": [-460, 520], "parameters": {"inputSource": "passthrough"}, "typeVersion": 1.1}, {"id": "034fc82c-b13a-4e72-ae86-97676d5b8867", "name": "Edit Fields1", "type": "n8n-nodes-base.set", "position": [860, -280], "parameters": {"options": {}, "assignments": {"assignments": [{"id": "ca7c30f2-444d-4551-988d-0f513e5ee4b1", "name": "file_id", "type": "string", "value": "={{ $json.id }}"}]}}, "typeVersion": 3.4}, {"id": "0c5d144c-77de-4d3b-a30b-3674ea858f3e", "name": "Create collection", "type": "n8n-nodes-base.httpRequest", "position": [-480, -760], "parameters": {"url": "http://QDRANTURL/collec