Status;\\nif (e.ackSkipReason) ackStatus = 'Skipped: ' + e.ackSkipReason;\\nelse if ($json.error) ackStatus = 'Failed: ' + ($json.error.message || $json.error);\\nelse ackStatus = e.ackMode === 'draft' ? 'Draft created' : 'Sent';\\nconst { ackText, ackHtml, ackRoute, ...rest } = e;\\nreturn { json: { ...rest, ackStatus } };"}, "typeVersion": 2}, {"id": "70c6fed8-8bc1-47c4-a68b-cd83dde8dbf0", "name": "Alert for Email Review", "type": "n8n-nodes-base.code", "position": [-2368, 6352], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Ask a human to triage emails the AI was not sure about.\\nconst e = $json;\\nconst reason = e.needsReview ? 'AI classification failed'\\n  : `Low confidence (${Math.round((e.confidence || 0) * 100)}% < ${Math.round((e.minConfidence || 0) * 100)}%)`;\\nconst text = [\\n  `:mag: *Email needs manual triage* - ${reason}`,\\n  `*AI guess:* ${e.category} / ${e.priority}${e.productArea ? ' / ' + e.productArea : ''}`,\\n  `*From:* ${e.fromName || ''} <${e.fromEmail}>  |  *Subject:* ${e.subject}`,\\n  e.summary ? `>${String(e.summary).replace(/\\\\n/g, '\\\\n>')}` : '',\\n  e.reasoning ? `_Why:_ ${e.reasoning}` : '',\\n  e.link ? `<${e.link}|Open email>` : `_Source: ${e.source}_`,\\n].filter(Boolean).join('\\\\n');\\nreturn { json: { ...e, reviewReason: reason, reviewText: text,\\n  reviewChannel: String(e.reviewSlackChannel || 'triage-review').replace('#', '') } };"}, "typeVersion": 2}, {"id": "941a4633-e8e0-4494-9550-994e40cc205d", "name": "Send Review Request to Slack", "type": "n8n-nodes-base.slack", "onError": "continueRegularOutput", "position": [-2144, 6352], "webhookId": "448f9ff1-5891-451c-973d-41f9390154dc", "parameters": {"text": "={{ $json.reviewText }}", "select": "channel", "channelId": {"__rl": true, "mode": "name", "value": "={{ $json.reviewChannel }}"}, "otherOptions": {"unfurl_links": false, "includeLinkToWorkflow": false}}, "typeVersion": 2.3}, {"id": "8d5bde18-c88d-4317-bd61-260f223bdf32", "name": "Return Review Outcome", "type": "n8n-nodes-base.code", "position": [-1936, 6352], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Return the email data plus review status.\\nconst e = $('Alert for Email Review').item.json;\\nconst { reviewText, ...rest } = e;\\nreturn { json: { ...rest, reviewAlertSent: !$json.error, escalationStatus: 'Sent to review (' + e.reviewReason + ')' } };"}, "typeVersion": 2}, {"id": "983fb096-e8c3-4c2e-84d6-6876e932c6d3", "name": "Generate Audit Log Entry", "type": "n8n-nodes-base.code", "position": [-1616, 6352], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Flatten the result into one audit-log row.\\nconst e = $json;\\nreturn { json: {\\n  'Logged At': new Date().toISOString(),\\n  'Received At': e.receivedAt || '',\\n  'Source': e.source || '',\\n  'From Name': e.fromName || '',\\n  'From Email': e.fromEmail || '',\\n  'Customer Company': e.customerCompany || '',\\n  'Subject': e.subject || '',\\n  'Customer Request': e.isCustomerRequest ? 'Yes' : 'No',\\n  'Category': e.category || '',\\n  'Priority': e.priority || '',\\n  'Confidence': e.confidence ?? '',\\n  'Product Area': e.productArea || '',\\n  'Sentiment': e.sentiment || '',\\n  'Ticket Title': e.title || '',\\n  'Summary': e.summary || '',\\n  'Routed To': e.assignedTo || '',\\n  'Jira Key': e.jiraKey || '',\\n  'Jira URL': e.jiraUrl || '',\\n  'Follow-up': e.isFollowUp ? 'Yes' : '',\\n  'Slack Sent': e.slackSent ? 'Yes' : '',\\n  'Customer Ack': e.ackStatus || '',\\n  'Status': e.escalationStatus || (e.isCustomerRequest ? 'Not escalated' : 'Ignored - not a customer request'),\\n  'Notes': e.skipReason || e.reasoning || e.jiraError || '',\\n  'Classified By': e.classifiedBy || '',\\n  'Email Link': e.link || '',\\n  'Message ID': e.messageId || '',\\n} };"}, "typeVersion": 2}, {"id": "1d20ba8f-f98e-4d7f-aeae-7f4da21a16f1", "name": "Add Entry to Triage Log", "type": "n8n-nodes-base.googleSheets", "onError": "continueRegularOutput", "position": [-1392, 6352], "parameters": {"