nBeUsedToMatch": true}, {"id": "model3", "type": "string", "display": true, "removed": false, "required": false, "displayName": "model3", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "prompt3 input tokens", "type": "string", "display": true, "removed": false, "required": false, "displayName": "prompt3 input tokens", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "prompt3 output tokens", "type": "string", "display": true, "removed": false, "required": false, "displayName": "prompt3 output tokens", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "model3 cost", "type": "string", "display": true, "removed": false, "required": false, "displayName": "model3 cost", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "cmCost", "type": "string", "display": true, "removed": false, "required": false, "displayName": "cmCost", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "upgradeCmCost", "type": "string", "display": true, "removed": false, "required": false, "displayName": "upgradeCmCost", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "fluxCost", "type": "string", "display": true, "removed": false, "required": false, "displayName": "fluxCost", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "klingCost", "type": "string", "display": true, "removed": false, "required": false, "displayName": "klingCost", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "totalCost", "type": "string", "display": true, "removed": false, "required": false, "displayName": "totalCost", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "datePosted", "type": "string", "display": true, "removed": false, "required": false, "displayName": "datePosted", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "row_number", "type": "string", "display": true, "removed": true, "readOnly": true, "required": false, "displayName": "row_number", "defaultMatch": false, "canBeUsedToMatch": true}], "mappingMode": "defineBelow", "matchingC