@n8n/n8n-nodes-langchain.outputParserStructured", "position": [1248, 288], "parameters": {"jsonSchemaExample": "[\\n  {\\n    \\"Caption\\": \\"Diver Removes Nets Off Whale \\ud83d\\udc0b #whalerescue #marinelife #oceanrescue #seahelpers #love #nature #instagood #explore #viral #savenature #oceanguardians #cleanoceans\\",\\n    \\"Idea\\": \\"Diver carefully cuts tangled net from distressed whale in open sea\\",\\n    \\"Environment\\": \\"Open ocean, sunlight beams through water, diver and whale, cinematic realism\\",\\n    \\"Sound\\": \\"Primary sound description under 15 words\\",\\n    \\"Status\\": \\"for production\\"\\n  }\\n]\\n"}, "typeVersion": 1.2}, {"id": "ad438d7b-b0f5-4801-87df-e313bfb9c83f", "name": "Save Idea & Metadata to Google Sheets", "type": "n8n-nodes-base.googleSheets", "position": [1424, 0], "parameters": {"columns": {"value": {"id": "==ROW()-1", "idea": "={{ $json.output[0].Idea }}", "caption": "={{ $json.output[0].Caption }}", "production": "={{ $json.output[0].Status }}", "sound_prompt": "={{ $json.output[0].Sound }}", "environment_prompt": "={{ $json.output[0].Environment }}"}, "schema": [{"id": "id", "type": "string", "display": true, "removed": false, "required": false, "displayName": "id", "defaultMatch": true, "canBeUsedToMatch": true}, {"id": "idea", "type": "string", "display": true, "required": false, "displayName": "idea", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "caption", "type": "string", "display": true, "required": false, "displayName": "caption", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "production", "type": "string", "display": true, "required": false, "displayName": "production", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "environment_prompt", "type": "string", "display": true, "required": false, "displayName": "environment_prompt", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "sound_prompt", "type": "string", "display": true, "required": false, "displayName": "sou