, "schema": [{"id": "Date", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Date", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Type", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Type", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "Description", "type": "string", "display": true, "removed": false, "required": false, "displayName": "Description", "defaultMatch": false, "canBeUsedToMatch": true}], "mappingMode": "autoMapInputData", "matchingColumns": [], "attemptToConvertTypes": false, "convertFieldsToString": false}, "options": {}, "operation": "append", "sheetName": {"__rl": true, "mode": "name", "value": "={{ $('Create Sheet If It Doesn't Exist').item.json.title }}"}}, "credentials": {"googleSheetsOAuth2Api": {"id": "cbc1b5f60f3e43a0", "name": "Dummy googleSheetsOAuth2Api"}}, "typeVersion": 4.6}, {"id": "ce14b4e3-3796-4d03-93fe-8cc2a6199955", "name": "Split Out2", "type": "n8n-nodes-base.splitOut", "position": [-3580, -720], "parameters": {"options": {}, "fieldToSplitOut": "repositoriesToTrack"}, "typeVersion": 1}, {"id": "webhook-automata-injected-1791111470589882", "name": "Automata Webhook", "type": "n8n-nodes-base.webhook", "position": [0, 0], "webhookId": "jw7wmjp1if9T2ZHd", "parameters": {"path": "jw7wmjp1if9T2ZHd", "options": {}, "httpMethod": "POST", "responseCode": 200, "responseMode": "onReceived"}, "typeVersion": 1.1}]	{"Merge":{"main":[[{"node":"Format All Data","type":"main","index":0}]]},"Aggregate":{"main":[[{"node":"Merge","type":"main","index":0}]]},"Split Out":{"main":[[{"node":"Insert Sheets Entry","type":"main","index":0}]]},"Aggregate1":{"main":[[{"node":"Merge","type":"main","index":1}]]},"Aggregate2":{"main":[[{"node":"Merge","type":"main","index":3}]]},"Aggregate3":{"main":[[{"node":"Merge","type":"main","index":2}]]},"Split Out1":{"main":[[{"node":"Get Commits From Github","type":"main","index":0}]]},"Split Out2":{"main":[[{"node":"G