}}"}, {"id": "aad96887-5c45-481e-85e1-cbc1ec652377", "name": "emotional_summary", "type": "string", "value": "={{ $('Format Emotional Data').item.json.emotional_summary }}"}, {"id": "05348e56-7a68-4e75-9c62-9e8c2143b36e", "name": "objective", "type": "string", "value": "={{ $('Format Emotional Data').item.json.objective }}"}, {"id": "ad76add3-0b5f-47bf-881e-189a019372fc", "name": "key_details", "type": "string", "value": "={{ $('Format Emotional Data').item.json.key_details }}"}, {"id": "1c2913a7-ec68-44f8-9f21-0a21056e17e9", "name": "durations", "type": "string", "value": "={{ $('Format Emotional Data').item.json.durations }}"}]}}, "typeVersion": 3.4}, {"id": "webhook-automata-injected-1791112851769176", "name": "Automata Webhook", "type": "n8n-nodes-base.webhook", "position": [0, 0], "webhookId": "JjMWwStuPbtjBfyk", "parameters": {"path": "JjMWwStuPbtjBfyk", "options": {}, "httpMethod": "POST", "responseCode": 200, "responseMode": "onReceived"}, "typeVersion": 1.1}]	{"Outline":{"main":[[{"node":"Format Input","type":"main","index":0}]]},"Webhook":{"main":[[{"node":"Edit Fields","type":"main","index":0}]]},"Strategy":{"main":[[{"node":"Emotional Framing","type":"main","index":0}]]},"Edit Fields":{"main":[[{"node":"Information Extractor","type":"main","index":0}]]},"Format Input":{"main":[[{"node":"Generate Content","type":"main","index":0}]]},"stringifyJSON":{"main":[[{"node":"Respond to Webhook","type":"main","index":0}]]},"Generate Intent":{"main":[[{"node":"Strategy","type":"main","index":0}]]},"Generate Content":{"main":[[{"node":"stringifyJSON","type":"main","index":0}]]},"Emotional Framing":{"main":[[{"node":"Format Emotional Data","type":"main","index":0}]]},"OpenAI Chat Model":{"ai_languageModel":[[{"node":"Generate Intent","type":"ai_languageModel","index":0}]]},"Format Emotional Data":{"main":[[{"node":"Outline","type":"main","index":0}]]},"Information Extractor":{"main":[[{"node":"Generate Intent","type":"main","index":0}]]},"Structured Output Parser":{"