type": "@n8n/n8n-nodes-langchain.memoryBufferWindow", "position": [-580, -1000], "parameters": {"contextWindowLength": 40}, "typeVersion": 1.3}, {"id": "f1e342a8-d50e-48a8-9d7a-850f8be93cff", "name": "When chat message received", "type": "@n8n/n8n-nodes-langchain.chatTrigger", "position": [-1160, -1200], "webhookId": "5f1c0c82-0ff9-40c7-9e2e-b1a96ffe24cd", "parameters": {"options": {}}, "typeVersion": 1.1}, {"id": "12902fa9-5bcb-4e8b-ac13-7f4cb6e7e1d0", "name": "Google Gemini Chat Model1", "type": "@n8n/n8n-nodes-langchain.lmChatGoogleGemini", "position": [-760, -1000], "parameters": {"options": {"maxOutputTokens": 8192}, "modelName": "models/gemini-2.0-flash-exp"}, "credentials": {"googlePalmApi": {"id": "11a68a950433485d", "name": "Dummy googlePalmApi"}}, "typeVersion": 1}, {"id": "1c5818d4-6251-4d14-8b4f-d1f3ddfbed38", "name": "text-embeddings-3-large1", "type": "@n8n/n8n-nodes-langchain.embeddingsOpenAi", "position": [-320, -840], "parameters": {"model": "text-embedding-3-large", "options": {}}, "credentials": {"openAiApi": {"id": "d83021c6ea6c47ee", "name": "Dummy openAiApi"}}, "typeVersion": 1}, {"id": "80056067-5d2b-4ac7-8e69-e75bd66a1ad4", "name": "Sticky Note9", "type": "n8n-nodes-base.stickyNote", "position": [-900, -1300], "parameters": {"color": 5, "width": 860, "height": 680, "content": "## \\ud83e\\udd16Retrieve Content from Qdrant Vector Store"}, "typeVersion": 1}, {"id": "b45b18e4-7773-4eec-837b-f43fc0eeb90c", "name": "Sticky Note10", "type": "n8n-nodes-base.stickyNote", "position": [-1280, -1300], "parameters": {"color": 4, "width": 340, "height": 320, "content": "## \\ud83d\\udde3\\ufe0f Chat with Your Documents"}, "typeVersion": 1}, {"id": "8fe891dd-dee6-4abb-bc09-d90e6d7bf3cb", "name": "Sticky Note11", "type": "n8n-nodes-base.stickyNote", "position": [-1360, -480], "parameters": {"color": 7, "width": 2880, "height": 1880, "content": "# Step 1 - Save Documents to Qdrant Vector Store"}, "typeVersion": 1}, {"id": "4a9bf716-3fc3-4ccc-b831-19a1afdb458