19408716-9f0d-494f-b79d-56a45df3f9d2	QAneGL7LmmVuAy1G	import	2026-10-04 11:16:13.817+00	2026-10-04 11:16:13.817+00	[{"id": "780a213c-0e81-4d95-910e-a467f316ebf6", "name": "Sticky Note1", "type": "n8n-nodes-base.stickyNote", "position": [-2460, 160], "parameters": {"width": 420, "height": 100, "content": "**Fires every morning at 8:00 AM server time to kick off the price-check cycle). Then it Reads the \\u201cmaster\\u201d Google Sheet tab, pulling each row\\u2019s product_url + last_price for processing**"}, "typeVersion": 1}, {"id": "9b9932ec-8cfd-4096-965b-592b13a1fb8e", "name": "Daily 8 AM Trigger", "type": "n8n-nodes-base.scheduleTrigger", "position": [-2420, 290], "parameters": {"rule": {"interval": [{"triggerAtHour": 8}]}}, "typeVersion": 1.2}, {"id": "6427045b-8b73-42f0-9dcc-768cbfac9c4a", "name": "Fetch Product List from Sheet", "type": "n8n-nodes-base.googleSheets", "position": [-2200, 290], "parameters": {"options": {}, "sheetName": {"__rl": true, "mode": "list", "value": "gid=0", "cachedResultUrl": "Replace with your google sheet url by downloading the googlesheet in the description of this automation", "cachedResultName": "product_data"}, "documentId": {"__rl": true, "mode": "list", "value": "18ZAjxmwanf6MS7JfrEX6ett6J-tOQi58B257hE6sOS4", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/18ZAjxmwanf6MS7JfrEX6ett6J-tOQi58B257hE6sOS4/edit?usp=drivesdk", "cachedResultName": "competitor_price_drop_automation"}}, "credentials": {"googleSheetsOAuth2Api": {"id": "cbc1b5f60f3e43a0", "name": "Dummy googleSheetsOAuth2Api"}}, "typeVersion": 4.5}, {"id": "0b4a1398-bb29-4f42-9475-eb08ab4dabfc", "name": "Process Each Product in Batches of 1", "type": "n8n-nodes-base.splitInBatches", "position": [-1980, 290], "parameters": {"options": {"reset": false}}, "typeVersion": 3}, {"id": "ccf9f9ca-b380-457e-9fc2-c6ffe1636984", "name": "Pause Between Requests", "type": "n8n-nodes-base.wait", "position": [-1760, 40], "webhookId": "335e69ac-d8ce-4704-a9c6-5a087f2859f8", "parameters": {"amount": 20}, "typeVersion": 1.1}, {"id": "aa49653b-cf9f-449b-953d-a9a19ac74187", "name": "Load Product Page HTML", "type": "n8n-nodes-base.httpRequest", "position": [-1540, 40], "parameters": {"url": "={{ $json.product_url }}", "options": {}, "jsonHeaders": "{\\n  \\"User-Agent\\": \\"Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:119.0) Gecko/20100101 Firefox/119.0\\",\\n  \\"Accept\\": \\"text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8\\",\\n  \\"Accept-Language\\": \\"en-IN,en;q=0.9\\",\\n  \\"Accept-Encoding\\": \\"gzip, deflate, br\\"\\n}", "sendHeaders": true, "specifyHeaders": "json"}, "typeVersion": 4.2}, {"id": "5dbc3d45-96d6-4b71-8d3f-2513f960e265", "name": "Extract Current Price from HTML", "type": "n8n-nodes-base.html", "position": [-1320, 40], "parameters": {"options": {}, "operation": "extractHtmlContent", "extractionValues": {"values": [{"key": "current_price", "cssSelector": ".price__regular > span.price-item--regular"}]}}, "typeVersion": 1.2}, {"id": "76ad9683-bae1-4f95-af09-44598d9448d1", "name": "Normalize Price Values", "type": "n8n-nodes-base.code", "position": [-1100, 40], "parameters": {"jsCode": "// HTML Extract result\\nconst scraped = items[0].json;\\n\\n// Original data from Wait node\\nconst original = $items(\\"Pause Between Requests\\")[0].json;\\n\\n// Clean and parse price\\nconst priceNum = parseFloat((scraped.current_price || \\"\\").replace(/[^0-9.]+/g, \\"\\"));\\n\\n// Original price from Google Sheet\\nconst lastPrice = parseFloat(original.price);\\n\\nreturn [{\\n  json: {\\n    product_url: original.product_url,\\n    row_number: original.row_number,\\n    last_price: lastPrice,\\n    current_price: priceNum\\n  }\\n}];\\n\\n"}, "typeVersion": 2}, {"id": "5feae925-0642-40d1-89be-c220a5a1c8a2", "name": "Compute Price Change", "type": "n8n-nodes-base.code", "position": [-880, 40], "parameters": {"jsCode": "// Get the incoming item\\nconst item = items[0].json;\\n\\n// Compute whether the price changed\\nconst priceChanged = item.last_price !== item.current_price;\\n\\n// Calculate percentage difference (will be NaN if last_price is null/0)\\nlet priceDiffPct = null;\\nif (item.last_price && item.last_price !== 0) {\\n  priceDiffPct = (\\n    ((item.current_price - item.last_price) / item.last_price) *\\n    100\\n  ).toFixed(2);\\n}\\n\\n// Return everything, including product_url and last_price\\nreturn [\\n  {\\n    json: {\\n      product_url: item.product_url,\\n      last_price: item.last_price,\\n      current_price: item.current_price,\\n      price_changed: priceChanged,\\n      price_diff_pct: priceDiffPct !== null ? parseFloat(priceDiffPct) : null,\\n      timestamp: new Date().toISOString(),\\n    },\\n  },\\n];\\n\\n\\n\\n"}, "typeVersion": 2}, {"id": "5dea2082-d5c5-4c13-8c71-ab7ac498632d", "name": "Clean Up Parsed Fields", "type": "n8n-nodes-base.code", "position": [-660, 40], "parameters": {"jsCode": "// Function node: 'items' is an array of incoming items\\nif (!items.length) {\\n  return [];\\n}\\n\\nconst input = items[0].json;\\nconst cleaned = {};\\n\\nfor (const key in input) {\\n  const cleanKey = key.replace(/\\\\t/g, '').trim();\\n  cleaned[cleanKey] = input[key];\\n}\\n\\nreturn [\\n  {\\n    json: {\\n      product_url: cleaned.product_url,\\n      last_price: cleaned.last_price,\\n      current_price: cleaned.current_price,\\n      price_changed: cleaned.price_changed,\\n      price_diff_pct: cleaned.price_diff_pct,\\n      timestamp: cleaned.timestamp,\\n    },\\n  },\\n];\\n\\n\\n"}, "typeVersion": 2}, {"id": "21c27cb9-c6bc-4cc3-9ad1-3d37fc6fbc3d", "name": "Is Price Changed?", "type": "n8n-nodes-base.if", "position": [-440, 40], "parameters": {"options": {}, "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "or", "conditions": [{"id": "5e285834-82ef-4c77-b96b-97661760f996", "operator": {"type": "boolean", "operation": "true", "singleValue": true}, "leftValue": "={{ $json.price_changed}}", "rightValue": "true"}]}}, "typeVersion": 2.2}, {"id": "50274daa-48c7-4c58-aaf5-264013582f97", "name": "Build Telegram Alert Message", "type": "n8n-nodes-base.code", "position": [-220, 140], "parameters": {"jsCode": "const itemsFormatted = [];\\n\\nfor (const item of items) {\\n  const data = item.json;\\n\\n  // Determine alert type\\n  const isDrop = data.price_diff_pct < 0;\\n  const alertType = isDrop ? \\"\\ud83d\\udcc9 *Price Drop Alert*\\" : \\"\\ud83d\\udcc8 *Price Hike Alert*\\";\\n\\n  // Format timestamp to IST\\n  const date = new Date(data.timestamp);\\n  const istOffset = 5.5 * 60 * 60 * 1000;\\n  const istDate = new Date(date.getTime() + istOffset);\\n  const formattedDate = istDate.toLocaleString(\\"en-IN\\", {\\n    day: \\"2-digit\\",\\n    month: \\"short\\",\\n    year: \\"numeric\\",\\n    hour: \\"2-digit\\",\\n    minute: \\"2-digit\\",\\n    hour12: true\\n  });\\n\\n  // Build message\\n  const message = `${alertType}\\n\\n\\ud83d\\udecd\\ufe0f *Product:* (${data.product_url})\\n\\ud83d\\udcb8 *Last Price:* $${data.last_price}\\n\\ud83d\\udcb0 *Current Price:* $${data.current_price}\\n\\ud83d\\udcca *Change:* ${data.price_diff_pct > 0 ? \\"+\\" : \\"\\"}${data.price_diff_pct}%\\n\\ud83d\\udd52 *Time:* ${formattedDate}`;\\n\\n  itemsFormatted.push({ json: { message } });\\n}\\n\\nreturn itemsFormatted;\\n\\n\\n"}, "typeVersion": 2}, {"id": "f62b1f32-fe79-43c3-ad17-0ff31fcdc489", "name": "Log Price History to Sheet", "type": "n8n-nodes-base.googleSheets", "position": [-220, -60], "parameters": {"columns": {"value": {"last_price": "={{ $json.last_price }}", "timestamp\\t": "={{ new Date($json.timestamp).toLocaleString('en-IN', {\\n  timeZone: 'Asia/Kolkata',\\n  day: '2-digit',\\n  month: 'short',\\n  year: 'numeric',\\n  hour: '2-digit',\\n  minute: '2-digit',\\n  hour12: true\\n}) }}\\n", "product_url": "={{ $json.product_url }}", "current_price": "={{ $json.current_price }}", "price_diff_pct": "={{ $json.price_diff_pct}}", "price_changed        ": "={{ $json.price_changed }}"}, "schema": [{"id": "timestamp\\t", "type": "string", "display": true, "required": false, "displayName": "timestamp\\t", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "product_url", "type": "string", "display": true, "required": false, "displayName": "product_url", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "current_price", "type": "string", "display": true, "removed": false, "required": false, "displayName": "current_price", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "last_price", "type": "string", "display": true, "removed": false, "required": false, "displayName": "last_price", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "price_changed        ", "type": "string", "display": true, "removed": false, "required": false, "displayName": "price_changed        ", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "price_diff_pct", "type": "string", "display": true, "removed": false, "required": false, "displayName": "price_diff_pct", "defaultMatch": false, "canBeUsedToMatch": true}], "mappingMode": "defineBelow", "matchingColumns": [], "attemptToConvertTypes": false, "convertFieldsToString": false}, "options": {"useAppend": true}, "operation": "append", "sheetName": {"__rl": true, "mode": "list", "value": 2110110902, "cachedResultUrl": "https://docs.google.com/spreadsheets/d/18ZAjxmwanf6MS7JfrEX6ett6J-tOQi58B257hE6sOS4/edit#gid=2110110902", "cachedResultName": "price_tracking"}, "documentId": {"__rl": true, "mode": "list", "value": "18ZAjxmwanf6MS7JfrEX6ett6J-tOQi58B257hE6sOS4", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/18ZAjxmwanf6MS7JfrEX6ett6J-tOQi58B257hE6sOS4/edit?usp=drivesdk", "cachedResultName": "competitor_price_drop_automation"}}, "credentials": {"googleSheetsOAuth2Api": {"id": "cbc1b5f60f3e43a0", "name": "Dummy googleSheetsOAuth2Api"}}, "typeVersion": 4.5}, {"id": "d5555b69-d7ee-4ab0-a851-5288de0d39cf", "name": "Pause Before Updating Sheet", "type": "n8n-nodes-base.wait", "position": [0, -60], "webhookId": "f8ba192a-211d-4b40-be9c-9994343eb162", "parameters": {"unit": "minutes", "amount": 1}, "typeVersion": 1.1}, {"id": "ade41bb7-fbe3-4e08-a7fa-6c85291dc9fa", "name": "Update Last Price in Master Sheet", "type": "n8n-nodes-base.googleSheets", "position": [220, -60], "parameters": {"columns": {"value": {"price": "={{ $json.current_price }}", "product_url": "={{ $json.product_url }}"}, "schema": [{"id": "product_url", "type": "string", "display": true, "removed": false, "required": false, "displayName": "product_url", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "price", "type": "string", "display": true, "required": false, "displayName": "price", "defaultMatch": false, "canBeUsedToMatch": true}, {"id": "row_number", "type": "string", "display": true, "removed": true, "readOnly": true, "required": false, "displayName": "row_number", "defaultMatch": false, "canBeUsedToMatch": true}], "mappingMode": "defineBelow", "matchingColumns": ["product_url"], "attemptToConvertTypes": false, "convertFieldsToString": false}, "options": {}, "operation": "update", "sheetName": {"__rl": true, "mode": "list", "value": "gid=0", "cachedResultUrl": "Replace with your google sheet url by downloading the googlesheet in the description of this automation", "cachedResultName": "product_data"}, "documentId": {"__rl": true, "mode": "list", "value": "18ZAjxmwanf6MS7JfrEX6ett6J-tOQi58B257hE6sOS4", "cachedResultUrl": "https://docs.google.com/spreadsheets/d/18ZAjxmwanf6MS7JfrEX6ett6J-tOQi58B257hE6sOS4/edit?usp=drivesdk", "cachedResultName": "competitor_price_drop_automation"}}, "credentials": {"googleSheetsOAuth2Api": {"id": "cbc1b5f60f3e43a0", "name": "Dummy googleSheetsOAuth2Api"}}, "typeVersion": 4.5}, {"id": "9ebdbe49-fda1-42f5-99d9-a5e1e3ab800f", "name": "Send Price Alert via Telegram", "type": "n8n-nodes-base.telegram", "position": [0, 215], "webhookId": "39287ce3-3a7e-4c7e-b8ee-b11ebb83bfb8", "parameters": {"text": "={{$json[\\"message\\"]}}", "chatId": "123456789", "additionalFields": {}}, "credentials": {"telegramApi": {"id": "XP2SJ3wLc8EY82QZ", "name": "Telegram API"}}, "typeVersion": 1.2}, {"id": "dcb4eff8-9d44-4016-a89a-787be943d0e9", "name": "Sticky Note", "type": "n8n-nodes-base.stickyNote", "position": [-2040, 440], "parameters": {"height": 100, "content": "**Iterates through all products in groups (e.g., 1 at a time) so we don\\u2019t overwhelm the target site with parallel requests.**"}, "typeVersion": 1}, {"id": "1a306c68-e652-4d63-b11e-96366c4a59ed", "name": "Sticky Note3", "type": "n8n-nodes-base.stickyNote", "position": [-1560, -60], "parameters": {"width": 360, "height": 80, "content": "**fires an HTTP GET for each product_url, then uses a CSS selector to pull the live price text from the returned HTML.**"}, "typeVersion": 1}, {"id": "81f8701a-219f-43a3-aceb-78f2298273cc", "name": "Sticky Note4", "type": "n8n-nodes-base.stickyNote", "position": [-1120, 180], "parameters": {"width": 380, "height": 100, "content": "**Strips currency symbols/commas to convert strings into numbers; compares last_price vs. current_price to calculate % change and set price_changed=true if different**"}, "typeVersion": 1}, {"id": "7fd2108e-5fcb-4ba6-938b-6c940f8a305f", "name": "Sticky Note5", "type": "n8n-nodes-base.stickyNote", "position": [-740, -100], "parameters": {"width": 220, "height": 120, "content": "\\n**Removes stray whitespace or malformed keys (e.g., stray tabs) so downstream nodes can read fields consistently**"}, "typeVersion": 1}, {"id": "7a525b63-e871-46b9-b0b0-4e25a6c7f2bb", "name": "Sticky Note6", "type": "n8n-nodes-base.stickyNote", "position": [-540, 180], "parameters": {"height": 100, "content": "**Only products with price_changed=true proceed to alerting and logging; unchanged items exit here.**"}, "typeVersion": 1}, {"id": "a6352172-9fa3-47b7-8bf0-c948fbe03701", "name": "Sticky Note7", "type": "n8n-nodes-base.stickyNote", "position": [-180, 420], "parameters": {"width": 380, "height": 80, "content": "\\n**Formats a human\\u2010readable message (product name/URL, old vs. new price, % change, timestamp) and pushes it to the configured Telegram chat**\\n"}, "typeVersion": 1}, {"id": "90b702f6-6e75-452d-9315-3f70c4157aab", "name": "Sticky Note8", "type": "n8n-nodes-base.stickyNote", "position": [-200, -160], "parameters": {"width": 520, "height": 80, "content": "\\n**Appends a row to Price_History with timestamp, % change, old vs. new price; then waits 1 minute before overwriting last_price in the master sheet with current_price.**\\n"}, "typeVersion": 1}, {"id": "3e3a4498-248d-408e-903b-916a035db039", "name": "Sticky Note9", "type": "n8n-nodes-base.stickyNote", "position": [-1300, -520], "parameters": {"width": 580, "content": "## Detailed Explanations of this automation\\n \\nYou can see the detailed step-by-step instructions here:\\n\\n- [Free n8n Web Scraping Competitor Price Tracking](https://www.blog.datahut.co/post/free-n8n-web-scraping-competitor-price-tracking)\\n- [YouTube Tutorial](https://www.youtube.com/watch?v=a9esT732mmE)\\n\\n\\n\\n\\n\\n\\nIs this conversation helpful so far?\\n\\n\\n"}, "typeVersion": 1}, {"id": "webhook-automata-injected-1791111459536", "name": "Automata Webhook", "type": "n8n-nodes-base.webhook", "position": [0, 0], "webhookId": "QAneGL7LmmVuAy1G", "parameters": {"path": "QAneGL7LmmVuAy1G", "options": {}, "httpMethod": "POST", "responseCode": 200, "responseMode": "onReceived"}, "typeVersion": 1.1}]	{"Is Price Changed?":{"main":[[{"node":"Build Telegram Alert Message","type":"main","index":0},{"node":"Log Price History to Sheet","type":"main","index":0}]]},"Daily 8 AM Trigger":{"main":[[{"node":"Fetch Product List from Sheet","type":"main","index":0}]]},"Compute Price Change":{"main":[[{"node":"Clean Up Parsed Fields","type":"main","index":0}]]},"Clean Up Parsed Fields":{"main":[[{"node":"Is Price Changed?","type":"main","index":0}]]},"Load Product Page HTML":{"main":[[{"node":"Extract Current Price from HTML","type":"main","index":0},{"node":"Process Each Product in Batches of 1","type":"main","index":0}]]},"Normalize Price Values":{"main":[[{"node":"Compute Price Change","type":"main","index":0}]]},"Pause Between Requests":{"main":[[{"node":"Load Product Page HTML","type":"main","index":0}]]},"Log Price History to Sheet":{"main":[[{"node":"Pause Before Updating Sheet","type":"main","index":0}]]},"Pause Before Updating Sheet":{"main":[[{"node":"Update Last Price in Master Sheet","type":"main","index":0}]]},"Build Telegram Alert Message":{"main":[[{"node":"Send Price Alert via Telegram","type":"main","index":0}]]},"Fetch Product List from Sheet":{"main":[[{"node":"Process Each Product in Batches of 1","type":"main","index":0}]]},"Send Price Alert via Telegram":{"main":[[{"node":"Process Each Product in Batches of 1","type":"main","index":0}]]},"Extract Current Price from HTML":{"main":[[{"node":"Normalize Price Values","type":"main","index":0}]]},"Process Each Product in Batches of 1":{"main":[[],[{"node":"Pause Between Requests","type":"main","index":0}]]},"Automata Webhook":{"main":[[{"node":"Fetch Product List from Sheet","type":"main","index":0}]]}}	\N	f	\N	[]
610ffa38-d4a3-4f61-b412-41aef6f7a79a	gPryDVHaa6eAuLNo	import	2026-10-03 17:48:58.563+00	2026-10-03 17:48:58.563+00	[{"id": "6c1fac23-740d-43dd-aef8-792bc9d671b1", "name": "Sticky Note", "type": "n8n-nodes-base.stickyNote", "position": [-3520, 3392], "parameters": {"width": 480, "height": 896, "content": "## Create Jira tickets from Gmail and Outlook support emails with OpenAI and Slack\\n\\n### How it works\\n\\nThis workflow monitors both Gmail and Outlook support inboxes, normalizes incoming messages into a shared format, and uses a reusable sub-workflow to classify each email with OpenAI. Based on the classification, it escalates urgent requests into Jira tickets or comments, routes uncertain emails to a Slack review queue, optionally acknowledges customers, and writes audit records to Google Sheets. It also includes Slack failure alerts for workflow errors.\\n\\n### Setup steps\\n\\n- Connect Gmail and Microsoft Outlook credentials for the email triggers and reply nodes.\\n- Configure OpenAI credentials for the classification chain and confirm the structured output parser matches the expected classification fields.\\n- Connect Jira credentials or API details, including the project, issue type, routing rules, and any custom fields used by the Jira payload builder.\\n- Connect Slack credentials and set the target escalation, review, and error-alert channels.\\n- Connect Google Sheets credentials and select the spreadsheet/sheet used for the triage audit log.\\n- Review the Workflow Configuration node values such as internalDomains, ignoreSenderPatterns, minConfidence, and maxBodyChars.\\n- If Microsoft Teams notifications are needed, configure the Teams webhook URL used by the escalation notification branch.\\n\\n### Customization\\n\\nAdjust the classification prompt, confidence threshold, sender ignore patterns, Jira routing logic, Slack channel mappings, acknowledgement behavior, and audit-log columns to match the support process."}, "typeVersion": 1}, {"id": "7daf8b14-5e9e-4a5f-9de0-0e67ecb9fbca", "name": "Sticky Note1", "type": "n8n-nodes-base.stickyNote", "position": [-2944, 3440], "parameters": {"color": 7, "width": 416, "height": 320, "content": "## Gmail email intake\\n\\nReceives new Gmail support messages and normalizes them into the common email shape used by the rest of the workflow."}, "typeVersion": 1}, {"id": "528dc7f6-7d92-4465-a239-6257b66ee9c5", "name": "Sticky Note2", "type": "n8n-nodes-base.stickyNote", "position": [-2944, 3792], "parameters": {"color": 7, "width": 416, "height": 320, "content": "## Outlook email intake\\n\\nReceives new Outlook support messages and normalizes Microsoft Graph email data into the shared email structure."}, "typeVersion": 1}, {"id": "0d111de6-0f09-4bd3-9969-78d9cebc3567", "name": "Sticky Note3", "type": "n8n-nodes-base.stickyNote", "position": [-2448, 3552], "parameters": {"color": 7, "width": 912, "height": 336, "content": "## Configure classification route\\n\\nAdds workflow configuration, starts the classification step, and routes the main pipeline based on the returned outcome."}, "typeVersion": 1}, {"id": "ae4e0f6f-8385-4434-95bd-89dad9c7647c", "name": "Sticky Note4", "type": "n8n-nodes-base.stickyNote", "position": [-1504, 3392], "parameters": {"color": 7, "width": 848, "height": 304, "content": "## Escalate and acknowledge\\n\\nInvokes the escalation sub-workflow for high-priority emails, then calls the acknowledgement step to reply to the customer when appropriate."}, "typeVersion": 1}, {"id": "21448b8c-c6dc-44d8-86a8-c5d301464ffc", "name": "Sticky Note5", "type": "n8n-nodes-base.stickyNote", "position": [-1504, 3728], "parameters": {"color": 7, "width": 416, "height": 304, "content": "## Send for review\\n\\nRoutes uncertain classification results into the review sub-workflow for human triage."}, "typeVersion": 1}, {"id": "c6a8e822-92c0-47ce-ab9a-cf6617774767", "name": "Sticky Note6", "type": "n8n-nodes-base.stickyNote", "position": [-848, 3728], "parameters": {"color": 7, "width": 416, "height": 304, "content": "## Call audit logging\\n\\nTriggers the audit-log sub-workflow after the main outcome has been processed."}, "typeVersion": 1}, {"id": "0203ee98-a739-4841-b0d0-d2c99042aea4", "name": "Sticky Note7", "type": "n8n-nodes-base.stickyNote", "position": [-2960, 4848], "parameters": {"color": 7, "width": 416, "height": 432, "content": "## Sub-workflow dispatcher\\n\\nEntry point for reusable sub-workflow calls; dispatches execution to classification, escalation, acknowledgement, review, or logging logic based on the step value."}, "typeVersion": 1}, {"id": "0a223da8-0ca7-4043-91a3-73df4fa506c9", "name": "Sticky Note8", "type": "n8n-nodes-base.stickyNote", "position": [-2416, 4128], "parameters": {"color": 7, "width": 416, "height": 320, "content": "## Classification pre-filter\\n\\nFilters out internal or automated senders before incurring AI usage and decides whether the message should be sent to the model."}, "typeVersion": 1}, {"id": "c1c3282d-2bdc-4516-b5c7-5c52201910f8", "name": "Sticky Note9", "type": "n8n-nodes-base.stickyNote", "position": [-1968, 4064], "parameters": {"color": 7, "width": 656, "height": 544, "content": "## AI email classification\\n\\nUses an OpenAI chat model with structured parsing to classify eligible emails, then merges the AI result back with the original email data."}, "typeVersion": 1}, {"id": "64f6ec4d-192d-42e9-95a6-8e2788bdc89a", "name": "Sticky Note10", "type": "n8n-nodes-base.stickyNote", "position": [-1280, 4192], "parameters": {"color": 7, "height": 352, "content": "## Skipped classification result\\n\\nProduces a logged result for messages that are intentionally not sent to AI."}, "typeVersion": 1}, {"id": "e8dcc9c7-2c80-41a7-98da-ff1313f1c7c6", "name": "Sticky Note11", "type": "n8n-nodes-base.stickyNote", "position": [-2416, 4880], "parameters": {"color": 7, "width": 640, "height": 320, "content": "## Resolve Jira routing\\n\\nBuilds the Jira routing decision, searches for an existing open ticket for the email thread, and branches between follow-up and new issue handling."}, "typeVersion": 1}, {"id": "158ab89b-5f38-4291-a8d2-cc05c9426b3d", "name": "Sticky Note12", "type": "n8n-nodes-base.stickyNote", "position": [-1744, 4768], "parameters": {"color": 7, "width": 416, "height": 320, "content": "## Update existing ticket\\n\\nAdds the incoming email as a follow-up comment on an existing Jira ticket and formats the result like a newly handled issue."}, "typeVersion": 1}, {"id": "f21ec1e1-e472-4705-b776-dbde45961fd5", "name": "Sticky Note13", "type": "n8n-nodes-base.stickyNote", "position": [-1744, 5152], "parameters": {"color": 7, "height": 320, "content": "## Create Jira issue\\n\\nCreates a new Jira issue when no open ticket exists for the email thread."}, "typeVersion": 1}, {"id": "f1e31ca7-6a0e-41e9-b8da-d1e27af4616a", "name": "Sticky Note14", "type": "n8n-nodes-base.stickyNote", "position": [-1296, 4896], "parameters": {"color": 7, "width": 640, "height": 304, "content": "## Build team notifications\\n\\nBuilds escalation messages, posts the main notification to Slack, and checks whether a Teams webhook is configured."}, "typeVersion": 1}, {"id": "b584a6f1-9551-4653-9342-4e5674404f22", "name": "Sticky Note15", "type": "n8n-nodes-base.stickyNote", "position": [-608, 4800], "parameters": {"color": 7, "width": 416, "height": 400, "content": "## Return escalation status\\n\\nOptionally posts a Microsoft Teams card and returns the final escalation result to the main pipeline."}, "typeVersion": 1}, {"id": "ae390ef0-d9a5-41d3-bf71-2481fbd75cdf", "name": "Sticky Note16", "type": "n8n-nodes-base.stickyNote", "position": [-2416, 5632], "parameters": {"color": 7, "width": 416, "height": 384, "content": "## Choose acknowledgement path\\n\\nPrepares the customer acknowledgement text and selects the appropriate email reply channel or no-reply outcome."}, "typeVersion": 1}, {"id": "4210f5f1-6845-492c-a7a9-b0b1ff023478", "name": "Sticky Note17", "type": "n8n-nodes-base.stickyNote", "position": [-1936, 5520], "parameters": {"color": 7, "width": 448, "height": 640, "content": "## Send customer replies\\n\\nSends or drafts Gmail acknowledgements, sends Outlook replies, and returns acknowledgement status to the caller."}, "typeVersion": 1}, {"id": "b3e8931d-442f-43ea-b040-038b39971c47", "name": "Sticky Note18", "type": "n8n-nodes-base.stickyNote", "position": [-2416, 6224], "parameters": {"color": 7, "width": 640, "height": 304, "content": "## Post review alert\\n\\nBuilds a human-review Slack alert for low-confidence emails and returns the review routing result."}, "typeVersion": 1}, {"id": "8a966c81-1198-41c3-a527-8497d5adcc39", "name": "Sticky Note19", "type": "n8n-nodes-base.stickyNote", "position": [-1664, 6192], "parameters": {"color": 7, "width": 416, "height": 320, "content": "## Append audit row\\n\\nFlattens the processed email outcome into an audit-log row and appends it to Google Sheets."}, "typeVersion": 1}, {"id": "9e0a1572-02f4-4c0a-bcac-0091150bde35", "name": "Sticky Note20", "type": "n8n-nodes-base.stickyNote", "position": [-2416, 6576], "parameters": {"color": 7, "width": 640, "height": 304, "content": "## Notify workflow failures\\n\\nHandles workflow-level errors by formatting a readable alert and posting it to Slack."}, "typeVersion": 1}, {"id": "60e1db40-59f7-46ca-8523-1ee8f07ac833", "name": "When Email Received in Gmail", "type": "n8n-nodes-base.gmailTrigger", "position": [-2896, 3600], "parameters": {"simple": false, "filters": {"q": "-from:me -category:promotions -category:social -category:updates -category:forums", "labelIds": ["INBOX"]}, "options": {}, "pollTimes": {"item": [{"mode": "everyMinute"}]}}, "typeVersion": 1.3}, {"id": "69f277ae-89d6-4ed2-8be8-ba6114e42fb9", "name": "When Email Received in Outlook", "type": "n8n-nodes-base.microsoftOutlookTrigger", "position": [-2896, 3952], "parameters": {"output": "raw", "filters": {}, "options": {}, "pollTimes": {"item": [{"mode": "everyMinute"}]}}, "typeVersion": 1}, {"id": "21d959db-6a22-4f3c-a09c-a2fa824319bc", "name": "Normalize Gmail Email", "type": "n8n-nodes-base.code", "position": [-2672, 3600], "parameters": {"jsCode": "// Normalise Gmail messages to the common email shape.\\nreturn $input.all().map(({ json: m }) => {\\n  const from = m.from?.value?.[0] || {};\\n  const text = m.text || String(m.html || '').replace(/<style[\\\\s\\\\S]*?<\\\\/style>/gi, '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');\\n  return { json: {\\n    source: 'Gmail',\\n    messageId: m.id || m.messageId || '',\\n    threadId: m.threadId || '',\\n    receivedAt: m.date ? new Date(m.date).toISOString() : new Date().toISOString(),\\n    fromName: from.name || '',\\n    fromEmail: (from.address || '').toLowerCase(),\\n    to: m.to?.text || '',\\n    subject: m.subject || '(no subject)',\\n    body: text,\\n    link: m.threadId ? `https://mail.google.com/mail/u/0/#all/${m.threadId}` : '',\\n    hasAttachments: Object.keys(m).some(k => k.startsWith('attachment')) || (m.attachments?.length > 0),\\n  } };\\n});"}, "typeVersion": 2}, {"id": "092d27b0-97b4-42f7-a515-c32406265efd", "name": "Normalize Outlook Email", "type": "n8n-nodes-base.code", "position": [-2672, 3952], "parameters": {"jsCode": "// Normalise Outlook (Microsoft Graph raw) messages to the common email shape.\\nreturn $input.all().map(({ json: m }) => {\\n  const from = m.from?.emailAddress || m.sender?.emailAddress || {};\\n  const html = m.body?.content || '';\\n  const text = m.body?.contentType === 'text' ? html :\\n    String(html).replace(/<style[\\\\s\\\\S]*?<\\\\/style>/gi, '').replace(/<br\\\\s*\\\\/?>/gi, '\\\\n').replace(/<\\\\/p>/gi, '\\\\n')\\n      .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/[ \\\\t]+/g, ' ');\\n  return { json: {\\n    source: 'Outlook',\\n    messageId: m.id || '',\\n    threadId: m.conversationId || '',\\n    receivedAt: m.receivedDateTime || new Date().toISOString(),\\n    fromName: from.name || '',\\n    fromEmail: (from.address || '').toLowerCase(),\\n    to: (m.toRecipients || []).map(r => r.emailAddress?.address).join(', '),\\n    subject: m.subject || '(no subject)',\\n    body: text || m.bodyPreview || '',\\n    link: m.webLink || '',\\n    hasAttachments: !!m.hasAttachments,\\n  } };\\n});"}, "typeVersion": 2}, {"id": "54c4a3e0-2500-4bf7-b6f6-34aff4ceb41d", "name": "Set Workflow Configuration", "type": "n8n-nodes-base.set", "position": [-2384, 3696], "parameters": {"options": {}, "assignments": {"assignments": [{"id": "d11c34c1-86a3-4c60-9049-47de35f0991b", "name": "internalDomains", "type": "string", "value": "example.com"}, {"id": "e5e3371e-9f2e-426f-9fbf-d16a07d3a3f3", "name": "ignoreSenderPatterns", "type": "string", "value": "noreply,no-reply,donotreply,mailer-daemon,notifications@,newsletter"}, {"id": "ae3c49d9-0943-402e-9aac-4b80b58c0edb", "name": "minConfidence", "type": "number", "value": 0.6}, {"id": "94803ca7-4715-455a-a55c-f17fdafa51fe", "name": "maxBodyChars", "type": "number", "value": 6000}, {"id": "835aab3d-c002-4fb5-a1ba-1656c3c013a2", "name": "jiraBaseUrl", "type": "string", "value": "https://your-domain.atlassian.net"}, {"id": "dce96970-cdb8-4e7d-bd7d-6057f40d8f4d", "name": "jiraProjectKey", "type": "string", "value": "SUP"}, {"id": "0e122879-026e-4b00-b6d8-3ce8424d8718", "name": "bugIssueType", "type": "string", "value": "Bug"}, {"id": "12bab9ee-459b-41e3-943c-a547a8470c05", "name": "issueIssueType", "type": "string", "value": "Task"}, {"id": "39d2291b-a6fe-4934-9c52-d2e30355fb69", "name": "requirementIssueType", "type": "string", "value": "Story"}, {"id": "be338ace-125f-4128-a0e8-ef6f3041e108", "name": "bugAssigneeAccountId", "type": "string", "value": ""}, {"id": "4f1be264-5d01-44de-94c8-5029d0ef7f51", "name": "issueAssigneeAccountId", "type": "string", "value": ""}, {"id": "2f80a56e-3635-49cc-bbf7-86d524b004be", "name": "requirementAssigneeAccountId", "type": "string", "value": ""}, {"id": "29ee38e6-5dad-4ba0-8d27-e54e890d2326", "name": "setJiraPriority", "type": "boolean", "value": true}, {"id": "5217e80c-0993-4801-9d96-0a88bb44639b", "name": "dedupByThread", "type": "boolean", "value": true}, {"id": "07620414-d936-49a2-b3ae-0ed0c378a1c9", "name": "bugSlackChannel", "type": "string", "value": "support-bugs"}, {"id": "bd1ba8c7-3a71-42c0-a63b-853bef35da3b", "name": "issueSlackChannel", "type": "string", "value": "support-issues"}, {"id": "dea6131b-8a56-4b3c-9187-93c484934810", "name": "requirementSlackChannel", "type": "string", "value": "product-requests"}, {"id": "d0ac31e9-abb7-4181-a60e-8c06b99bb309", "name": "reviewSlackChannel", "type": "string", "value": "triage-review"}, {"id": "a5baccf3-e98d-4f36-8640-3058de33e85b", "name": "teamsWebhookUrl", "type": "string", "value": ""}, {"id": "b2d516c6-4ce0-40a8-9919-9916b1d3d5eb", "name": "ackMode", "type": "string", "value": "off"}, {"id": "eb4ed085-5577-48ee-a9b8-0d059d7540ce", "name": "companyName", "type": "string", "value": "Your Company"}, {"id": "18b2a88d-24ca-43f1-8eb9-b1933913d97e", "name": "ackSignature", "type": "string", "value": "Customer Success Team"}]}, "includeOtherFields": true}, "typeVersion": 3.4}, {"id": "f4388c67-7c2c-4192-8c9f-cf6ed977d7d4", "name": "Prepare Step for Classification", "type": "n8n-nodes-base.set", "position": [-2112, 3696], "parameters": {"options": {}, "assignments": {"assignments": [{"id": "94affcd1-c387-4de5-ad89-1b936752810b", "name": "step", "type": "string", "value": "classify"}]}, "includeOtherFields": true}, "typeVersion": 3.4}, {"id": "ecf8d929-9172-4367-ab68-98b971184384", "name": "Execute Email Classification", "type": "n8n-nodes-base.executeWorkflow", "position": [-1888, 3696], "parameters": {"mode": "each", "options": {"waitForSubWorkflow": true}, "workflowId": {"__rl": true, "mode": "id", "value": "={{ $workflow.id }}"}, "workflowInputs": {"value": {}, "schema": [], "mappingMode": "defineBelow", "matchingColumns": [], "attemptToConvertTypes": false, "convertFieldsToString": true}}, "typeVersion": 1.2}, {"id": "4334dbf3-aa44-4624-91b0-57993ffeeeeb", "name": "Route by Classification Outcome", "type": "n8n-nodes-base.switch", "position": [-1664, 3696], "parameters": {"rules": {"values": [{"outputKey": "Escalate", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "loose"}, "combinator": "and", "conditions": [{"id": "2c8d53ad-d493-4d30-a07c-11dc9137bd8b", "operator": {"type": "boolean", "operation": "true", "singleValue": true}, "leftValue": "={{ $json.isCustomerRequest === true && ['New Requirement','Issue','Bug'].includes($json.category) && Number($json.confidence) >= Number($json.minConfidence) }}", "rightValue": ""}]}, "renameOutput": true}, {"outputKey": "Review", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "loose"}, "combinator": "and", "conditions": [{"id": "424d7f50-7057-40b7-a8e9-9927af8c8482", "operator": {"type": "boolean", "operation": "true", "singleValue": true}, "leftValue": "={{ $json.needsReview === true || ($json.isCustomerRequest === true && Number($json.confidence) < Number($json.minConfidence)) }}", "rightValue": ""}]}, "renameOutput": true}]}, "options": {"fallbackOutput": "extra", "renameFallbackOutput": "Ignore"}, "looseTypeValidation": true}, "typeVersion": 3.2}, {"id": "642aa583-23d5-481d-9a19-bdafd519881f", "name": "Prepare Step for Escalation", "type": "n8n-nodes-base.set", "position": [-1456, 3536], "parameters": {"options": {}, "assignments": {"assignments": [{"id": "8ea97d73-bd72-4a68-b8b6-2fae8ebf53cf", "name": "step", "type": "string", "value": "escalate"}]}, "includeOtherFields": true}, "typeVersion": 3.4}, {"id": "dd53e473-38aa-4e8c-8ba5-d84221656980", "name": "Execute Escalation Workflow", "type": "n8n-nodes-base.executeWorkflow", "position": [-1232, 3536], "parameters": {"mode": "each", "options": {"waitForSubWorkflow": true}, "workflowId": {"__rl": true, "mode": "id", "value": "={{ $workflow.id }}"}, "workflowInputs": {"value": {}, "schema": [], "mappingMode": "defineBelow", "matchingColumns": [], "attemptToConvertTypes": false, "convertFieldsToString": true}}, "typeVersion": 1.2}, {"id": "12ca9fa7-d331-4f0e-9cbb-26800333567f", "name": "Prepare Step for Acknowledgement", "type": "n8n-nodes-base.set", "position": [-1008, 3536], "parameters": {"options": {}, "assignments": {"assignments": [{"id": "44c8abd5-e28e-4f94-bb07-97e6e571ea46", "name": "step", "type": "string", "value": "acknowledge"}]}, "includeOtherFields": true}, "typeVersion": 3.4}, {"id": "92cfd208-0456-4538-bd8f-ae8dfbae78e7", "name": "Execute Customer Acknowledgement", "type": "n8n-nodes-base.executeWorkflow", "position": [-784, 3536], "parameters": {"mode": "each", "options": {"waitForSubWorkflow": true}, "workflowId": {"__rl": true, "mode": "id", "value": "={{ $workflow.id }}"}, "workflowInputs": {"value": {}, "schema": [], "mappingMode": "defineBelow", "matchingColumns": [], "attemptToConvertTypes": false, "convertFieldsToString": true}}, "typeVersion": 1.2}, {"id": "e7e5266d-db60-4597-8aae-0d4c39d7b5ed", "name": "Prepare Step for Review", "type": "n8n-nodes-base.set", "position": [-1456, 3856], "parameters": {"options": {}, "assignments": {"assignments": [{"id": "f6ded644-f041-4463-8a5b-d9ecefe1d8fb", "name": "step", "type": "string", "value": "review"}]}, "includeOtherFields": true}, "typeVersion": 3.4}, {"id": "72fed49a-859c-4768-9318-1d8e3f49f6e9", "name": "Execute Review Queue Workflow", "type": "n8n-nodes-base.executeWorkflow", "position": [-1232, 3856], "parameters": {"mode": "each", "options": {"waitForSubWorkflow": true}, "workflowId": {"__rl": true, "mode": "id", "value": "={{ $workflow.id }}"}, "workflowInputs": {"value": {}, "schema": [], "mappingMode": "defineBelow", "matchingColumns": [], "attemptToConvertTypes": false, "convertFieldsToString": true}}, "typeVersion": 1.2}, {"id": "13b76e42-3fa0-4d78-9da7-ce2c981b5ac2", "name": "Prepare Step for Logging", "type": "n8n-nodes-base.set", "position": [-800, 3872], "parameters": {"options": {}, "assignments": {"assignments": [{"id": "1e7ebf32-77e6-4c14-9d8b-b7cf1c9fc900", "name": "step", "type": "string", "value": "log"}]}, "includeOtherFields": true}, "typeVersion": 3.4}, {"id": "944289cb-85ff-49f6-bd8f-5d786db6d40a", "name": "Execute Audit Log Workflow", "type": "n8n-nodes-base.executeWorkflow", "position": [-576, 3872], "parameters": {"mode": "each", "options": {"waitForSubWorkflow": true}, "workflowId": {"__rl": true, "mode": "id", "value": "={{ $workflow.id }}"}, "workflowInputs": {"value": {}, "schema": [], "mappingMode": "defineBelow", "matchingColumns": [], "attemptToConvertTypes": false, "convertFieldsToString": true}}, "typeVersion": 1.2}, {"id": "a9c50f66-08f9-49b3-8aad-3301a4c662f1", "name": "Route by Workflow Step", "type": "n8n-nodes-base.switch", "position": [-2688, 5040], "parameters": {"rules": {"values": [{"outputKey": "classify", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "47dbd1e5-0d92-4486-bbc9-9747d92c8e60", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.step }}", "rightValue": "classify"}]}, "renameOutput": true}, {"outputKey": "escalate", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "39f7df9c-3e51-4b91-91ce-a595bf0a53fe", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.step }}", "rightValue": "escalate"}]}, "renameOutput": true}, {"outputKey": "acknowledge", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "5fa3b6f1-5751-453d-b7ad-fa08427256f6", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.step }}", "rightValue": "acknowledge"}]}, "renameOutput": true}, {"outputKey": "review", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "a1122db7-2481-41f5-9bb2-fd4e078eb6f1", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.step }}", "rightValue": "review"}]}, "renameOutput": true}, {"outputKey": "log", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "10dd5d24-b9e3-4c1a-8289-70e8a6d16ba9", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.step }}", "rightValue": "log"}]}, "renameOutput": true}]}, "options": {}}, "typeVersion": 3.2}, {"id": "65d60bf0-05d2-4905-b014-e98e78ed32e6", "name": "Filter and Prepare for AI", "type": "n8n-nodes-base.code", "position": [-2368, 4304], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Pre-filter: drop internal / automated senders before spending AI tokens,\\n// strip quoted reply history and trim the body.\\nconst e = $json;\\nconst fromEmail = String(e.fromEmail || '').toLowerCase().trim();\\nconst domain = fromEmail.split('@')[1] || '';\\nconst list = v => String(v || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);\\nconst internalDomains = list(e.internalDomains);\\nconst ignorePatterns = list(e.ignoreSenderPatterns);\\n\\nlet skipReason = '';\\nif (!fromEmail) skipReason = 'No sender address';\\nelse if (internalDomains.includes(domain)) skipReason = 'Internal sender (' + domain + ')';\\nelse if (ignorePatterns.some(p => fromEmail.includes(p))) skipReason = 'Automated / no-reply sender';\\n\\n// Remove quoted history (\\"On ... wrote:\\", \\"From: ... Sent:\\", lines starting with \\">\\")\\nlet body = String(e.body || '');\\nconst cut = body.search(/\\\\n(On .{0,200}wrote:|-{2,}\\\\s*Original Message|From:\\\\s.+\\\\n(Sent|Date):)/i);\\nif (cut > 0) body = body.slice(0, cut);\\nbody = body.split('\\\\n').filter(l => !l.trim().startsWith('>')).join('\\\\n')\\n  .replace(/\\\\n{3,}/g, '\\\\n\\\\n').trim();\\nconst max = Number(e.maxBodyChars) || 6000;\\nif (body.length > max) body = body.slice(0, max) + '\\\\n...[truncated]';\\n\\nreturn { json: { ...e, fromEmail, body, skipAI: !!skipReason, skipReason } };"}, "typeVersion": 2}, {"id": "914f6e66-5232-48f5-b6b1-1a2cacfcc733", "name": "Check AI Classification Needed", "type": "n8n-nodes-base.if", "position": [-2144, 4304], "parameters": {"options": {}, "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "loose"}, "combinator": "and", "conditions": [{"id": "cb163c9f-d0c0-4885-a8b6-16498feb1eae", "operator": {"type": "boolean", "operation": "true", "singleValue": true}, "leftValue": "={{ !$json.skipAI }}", "rightValue": ""}]}, "looseTypeValidation": true}, "typeVersion": 2.2}, {"id": "d5a08ab3-e3c3-4e72-bd7a-2441000cd1fa", "name": "AI Email Classifier", "type": "@n8n/n8n-nodes-langchain.chainLlm", "onError": "continueRegularOutput", "maxTries": 3, "position": [-1808, 4192], "parameters": {"text": "=Classify this inbound email.\\n\\nReceived via: {{ $json.source }}\\nFrom: {{ $json.fromName }} <{{ $json.fromEmail }}>\\nSubject: {{ $json.subject }}\\nHas attachments: {{ $json.hasAttachments }}\\n\\nBody:\\n\\"\\"\\"\\n{{ $json.body }}\\n\\"\\"\\"", "batching": {}, "messages": {"messageValues": [{"message": "You are a senior customer-support triage analyst for a B2B software company. You read ONE inbound email and decide whether it is a genuine customer request and, if so, what kind.\\n\\nCategories (pick exactly one):\\n- \\"New Requirement\\": the customer asks for a new feature, enhancement, change request, integration, report, or customisation that does not exist today.\\n- \\"Issue\\": something is not working as the customer expects but it is NOT clearly a software defect - access/login problems, configuration or data questions, how-to confusion, performance complaints, service outages, billing/account problems.\\n- \\"Bug\\": a reproducible software defect - error messages, crashes, wrong calculations, broken UI, features behaving contrary to their documented behaviour.\\n- \\"Other\\": newsletters, marketing, sales pitches, vendor/recruiter outreach, invoices from suppliers, auto-replies, thank-you notes, meeting logistics, spam, or anything not requiring product/support action.\\n\\nPriority:\\n- \\"Critical\\": production down, data loss/corruption, security incident, many users blocked, or explicit severe business impact/deadline today.\\n- \\"High\\": key workflow blocked for some users, no workaround, or strong urgency/escalation language.\\n- \\"Medium\\": workaround exists or limited impact; most feature requests from active customers.\\n- \\"Low\\": cosmetic, nice-to-have, general questions.\\n\\nRules:\\n- isCustomerRequest is true only for New Requirement, Issue or Bug coming from a customer/client/end-user (not vendors, recruiters, or marketing).\\n- If the email mixes several asks, classify by the most severe one (Bug > Issue > New Requirement) and mention the others in summary.\\n- title: an actionable ticket title, max 100 characters, no customer name.\\n- summary: 2-4 sentences a developer can act on; include versions, modules, IDs, error text if present.\\n- stepsToReproduce: only for Bug, otherwise empty string.\\n- productArea: the module/feature mentioned (e.g. \\"Billing\\", \\"Login\\", \\"Reports\\", \\"API\\", \\"Mobile App\\"), or \\"General\\".\\n- customerCompany: infer from signature or email domain if possible, else empty string.\\n- confidence: 0-1, how sure you are about the category.\\n- Ignore signatures, legal disclaimers and quoted previous messages.\\n- Respond ONLY with the structured output."}]}, "promptType": "define", "hasOutputParser": true}, "retryOnFail": true, "typeVersion": 1.7, "waitBetweenTries": 3000}, {"id": "f00da2fb-7748-425a-a1b1-61b833997885", "name": "OpenAI GPT-4.1 Mini", "type": "@n8n/n8n-nodes-langchain.lmChatOpenAi", "position": [-1808, 4448], "parameters": {"model": {"__rl": true, "mode": "list", "value": "gpt-4.1-mini"}, "options": {"temperature": 0.1}}, "typeVersion": 1.2}, {"id": "887bfe67-8bd7-4ebe-a011-0025ca41d2ba", "name": "Parse Classification Result", "type": "@n8n/n8n-nodes-langchain.outputParserStructured", "position": [-1472, 4448], "parameters": {"schemaType": "manual", "inputSchema": "{\\n  \\"type\\": \\"object\\",\\n  \\"properties\\": {\\n    \\"isCustomerRequest\\": {\\n      \\"type\\": \\"boolean\\"\\n    },\\n    \\"category\\": {\\n      \\"type\\": \\"string\\",\\n      \\"enum\\": [\\n        \\"New Requirement\\",\\n        \\"Issue\\",\\n        \\"Bug\\",\\n        \\"Other\\"\\n      ]\\n    },\\n    \\"priority\\": {\\n      \\"type\\": \\"string\\",\\n      \\"enum\\": [\\n        \\"Critical\\",\\n        \\"High\\",\\n        \\"Medium\\",\\n        \\"Low\\"\\n      ]\\n    },\\n    \\"confidence\\": {\\n      \\"type\\": \\"number\\",\\n      \\"minimum\\": 0,\\n      \\"maximum\\": 1\\n    },\\n    \\"productArea\\": {\\n      \\"type\\": \\"string\\"\\n    },\\n    \\"title\\": {\\n      \\"type\\": \\"string\\"\\n    },\\n    \\"summary\\": {\\n      \\"type\\": \\"string\\"\\n    },\\n    \\"customerName\\": {\\n      \\"type\\": \\"string\\"\\n    },\\n    \\"customerCompany\\": {\\n      \\"type\\": \\"string\\"\\n    },\\n    \\"sentiment\\": {\\n      \\"type\\": \\"string\\",\\n      \\"enum\\": [\\n        \\"Positive\\",\\n        \\"Neutral\\",\\n        \\"Negative\\",\\n        \\"Angry\\"\\n      ]\\n    },\\n    \\"stepsToReproduce\\": {\\n      \\"type\\": \\"string\\"\\n    },\\n    \\"reasoning\\": {\\n      \\"type\\": \\"string\\"\\n    }\\n  },\\n  \\"required\\": [\\n    \\"isCustomerRequest\\",\\n    \\"category\\",\\n    \\"priority\\",\\n    \\"confidence\\",\\n    \\"productArea\\",\\n    \\"title\\",\\n    \\"summary\\",\\n    \\"customerName\\",\\n    \\"customerCompany\\",\\n    \\"sentiment\\",\\n    \\"stepsToReproduce\\",\\n    \\"reasoning\\"\\n  ]\\n}"}, "typeVersion": 1.3}, {"id": "e6fb23d1-6a78-40ec-affa-5374fdf21cf6", "name": "Combine Email and Classification", "type": "n8n-nodes-base.code", "position": [-1456, 4192], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Combine the original email with the AI classification.\\nconst src = $('Filter and Prepare for AI').item.json;\\nconst ai = $json.output || {};\\nconst ok = !!ai.category;\\nreturn { json: {\\n  ...src,\\n  isCustomerRequest: ok ? !!ai.isCustomerRequest : false,\\n  category: ok ? ai.category : 'Unclassified',\\n  priority: ai.priority || 'Medium',\\n  confidence: typeof ai.confidence === 'number' ? ai.confidence : 0,\\n  productArea: ai.productArea || '',\\n  title: ai.title || src.subject || '(no subject)',\\n  summary: ai.summary || '',\\n  customerName: ai.customerName || src.fromName || '',\\n  customerCompany: ai.customerCompany || '',\\n  sentiment: ai.sentiment || 'Neutral',\\n  stepsToReproduce: ai.stepsToReproduce || '',\\n  reasoning: ai.reasoning || (ok ? '' : 'AI classification failed: ' + ($json.error?.message || $json.error || 'no output')),\\n  needsReview: !ok,\\n  classifiedBy: 'AI',\\n  classifiedAt: new Date().toISOString(),\\n} };"}, "typeVersion": 2}, {"id": "46753dcc-7e5e-4116-bc58-b14894551514", "name": "Record Skipped AI Classification", "type": "n8n-nodes-base.code", "position": [-1232, 4400], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Not sent to AI - keep a record so it can still be logged.\\nconst e = $json;\\nreturn { json: {\\n  ...e,\\n  isCustomerRequest: false,\\n  category: 'Other',\\n  priority: 'Low',\\n  confidence: 1,\\n  productArea: '',\\n  title: e.subject || '(no subject)',\\n  summary: 'Skipped: ' + e.skipReason,\\n  customerName: e.fromName || '',\\n  customerCompany: '',\\n  sentiment: 'Neutral',\\n  stepsToReproduce: '',\\n  reasoning: e.skipReason,\\n  needsReview: false,\\n  classifiedBy: 'rules',\\n  classifiedAt: new Date().toISOString(),\\n} };"}, "typeVersion": 2}, {"id": "36012838-37f5-446c-a7c0-1af2ac6672e8", "name": "Build Jira Routing Decision", "type": "n8n-nodes-base.code", "position": [-2368, 5040], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Build the routing decision and Jira payload from Workflow Configuration.\\nconst e = $json;\\nconst ROUTES = {\\n  'Bug':             { issueType: e.bugIssueType || 'Bug',           assigneeAccountId: e.bugAssigneeAccountId,         slackChannel: e.bugSlackChannel,         labels: ['customer-email', 'bug'] },\\n  'Issue':           { issueType: e.issueIssueType || 'Task',        assigneeAccountId: e.issueAssigneeAccountId,       slackChannel: e.issueSlackChannel,       labels: ['customer-email', 'issue'] },\\n  'New Requirement': { issueType: e.requirementIssueType || 'Story', assigneeAccountId: e.requirementAssigneeAccountId, slackChannel: e.requirementSlackChannel, labels: ['customer-email', 'requirement'] },\\n};\\n// Optional: route specific product areas elsewhere, e.g. { billing: { slackChannel: 'billing' } }\\nconst AREA_OVERRIDES = {};\\n\\nlet route = { ...(ROUTES[e.category] || ROUTES['Issue']) };\\nconst area = String(e.productArea || '').toLowerCase();\\nfor (const [key, ov] of Object.entries(AREA_OVERRIDES)) {\\n  if (area.includes(key)) { route = { ...route, ...ov }; break; }\\n}\\nroute.slackChannel = String(route.slackChannel || '').replace('#', '');\\nroute.owner = `${e.category} owner (#${route.slackChannel})`;\\n\\n// Stable Jira label per email thread, used to find the open ticket for replies\\nconst threadKey = String(e.threadId || e.messageId || e.subject || '');\\nlet h = 5381;\\nfor (let i = 0; i < threadKey.length; i++) h = ((h << 5) + h + threadKey.charCodeAt(i)) >>> 0;\\nconst threadLabel = 'email-thread-' + h.toString(36);\\n\\nconst description = [\\n  `*Source:* customer email via ${e.source}`,\\n  `*From:* ${e.fromName || ''} <${e.fromEmail}>${e.customerCompany ? ' - ' + e.customerCompany : ''}`,\\n  `*Received:* ${e.receivedAt}`,\\n  `*Category / priority:* ${e.category} / ${e.priority} (AI confidence ${Math.round((e.confidence || 0) * 100)}%)`,\\n  `*Product area:* ${e.productArea || 'General'}  |  *Sentiment:* ${e.sentiment}`,\\n  '', 'h3. Summary', e.summary || '',\\n  e.stepsToReproduce ? '\\\\nh3. Steps to reproduce\\\\n' + e.stepsToReproduce : '',\\n  '', 'h3. Original email', `*Subject:* ${e.subject}`,\\n  '{noformat}', String(e.body || '').slice(0, 20000), '{noformat}',\\n].join('\\\\n');\\n\\nconst PRIORITY_MAP = { Critical: 'Highest', High: 'High', Medium: 'Medium', Low: 'Low' };\\nconst fields = {\\n  project: { key: e.jiraProjectKey },\\n  issuetype: { name: route.issueType },\\n  summary: String(e.title || e.subject || 'Customer request').slice(0, 250),\\n  description,\\n  labels: [...route.labels, threadLabel],\\n};\\nif (e.setJiraPriority && PRIORITY_MAP[e.priority]) fields.priority = { name: PRIORITY_MAP[e.priority] };\\nif (route.assigneeAccountId) fields.assignee = { accountId: route.assigneeAccountId };\\n\\nreturn { json: {\\n  ...e,\\n  route,\\n  jiraBaseUrl: String(e.jiraBaseUrl || '').replace(/\\\\/$/, ''),\\n  jiraPayload: { fields },\\n  threadLabel,\\n  dedupEnabled: e.dedupByThread !== false && !!threadKey,\\n  dedupJql: `labels = \\"${threadLabel}\\" AND statusCategory != Done ORDER BY created DESC`,\\n  followUpComment: [\\n    `Follow-up email from ${e.fromName || ''} <${e.fromEmail}> at ${e.receivedAt}`,\\n    `AI read: ${e.category} / ${e.priority} - ${e.summary || ''}`,\\n    '{noformat}', String(e.body || '').slice(0, 15000), '{noformat}',\\n  ].join('\\\\n'),\\n} };"}, "typeVersion": 2}, {"id": "3c55cf20-8b4d-4191-873a-b9ca9e673d3a", "name": "Search Open Jira Tickets", "type": "n8n-nodes-base.jira", "onError": "continueRegularOutput", "position": [-2144, 5040], "parameters": {"limit": 1, "options": {"jql": "={{ $json.dedupJql }}", "fields": "key,status"}, "operation": "getAll"}, "typeVersion": 1, "alwaysOutputData": true}, {"id": "e359cba8-c573-4b09-b083-cb48bc07babb", "name": "Check If Ticket Exists", "type": "n8n-nodes-base.if", "position": [-1936, 5040], "parameters": {"options": {}, "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "loose"}, "combinator": "and", "conditions": [{"id": "a512d684-e176-44ae-b90d-df8701ae57fe", "operator": {"type": "boolean", "operation": "true", "singleValue": true}, "leftValue": "={{ $('Build Jira Routing Decision').item.json.dedupEnabled && !!$json.key }}", "rightValue": ""}]}, "looseTypeValidation": true}, "typeVersion": 2.2}, {"id": "eb8ea324-7926-4fa5-80d3-44ae7f035d50", "name": "Comment on Existing Ticket", "type": "n8n-nodes-base.jira", "onError": "continueRegularOutput", "position": [-1696, 4944], "parameters": {"comment": "={{ $('Build Jira Routing Decision').item.json.followUpComment }}", "options": {}, "issueKey": "={{ $json.key }}", "resource": "issueComment"}, "typeVersion": 1}, {"id": "f6fb2a72-2a5d-48bf-84ad-24023392f205", "name": "Record Ticket Follow-Up", "type": "n8n-nodes-base.code", "position": [-1472, 4944], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Comment added to the open ticket: expose its key like a newly created issue.\\nconst key = $('Search Open Jira Tickets').item.json.key || '';\\nreturn { json: { key: $json.error ? '' : key, isFollowUp: true, error: $json.error } };"}, "typeVersion": 2}, {"id": "000c879d-3d31-4416-aeed-cd9729680f0d", "name": "Post New Jira Issue", "type": "n8n-nodes-base.httpRequest", "onError": "continueRegularOutput", "maxTries": 2, "position": [-1696, 5312], "parameters": {"url": "={{ $('Build Jira Routing Decision').item.json.jiraBaseUrl }}/rest/api/2/issue", "method": "POST", "options": {}, "jsonBody": "={{ JSON.stringify($('Build Jira Routing Decision').item.json.jiraPayload) }}", "sendBody": true, "specifyBody": "json", "authentication": "predefinedCredentialType", "nodeCredentialType": "jiraSoftwareCloudApi"}, "retryOnFail": true, "typeVersion": 4.2}, {"id": "6c914524-9763-4866-b545-71c7b0b16a8e", "name": "Create Notification Messages", "type": "n8n-nodes-base.code", "position": [-1248, 5040], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Build Slack and Teams messages from the Jira result.\\nconst e = $('Build Jira Routing Decision').item.json;\\nconst res = $json;\\nconst jiraKey = res.key || '';\\nconst isFollowUp = !!res.isFollowUp;\\nconst jiraUrl = jiraKey ? `${e.jiraBaseUrl}/browse/${jiraKey}` : '';\\nconst jiraError = jiraKey ? '' : String(res.error?.message || res.error || res.message || 'Jira issue not created');\\nconst icon = { 'Bug': ':beetle:', 'Issue': ':warning:', 'New Requirement': ':bulb:' }[e.category] || ':envelope:';\\nconst urgent = e.priority === 'Critical' && !isFollowUp ? '<!channel> ' : '';\\n\\nconst slackText = [\\n  isFollowUp ? `:speech_balloon: *Customer follow-up* on ${jiraKey} - ${e.category} / ${e.priority}`\\n             : `${urgent}${icon} *New customer ${e.category}* - *${e.priority}* priority`,\\n  `*${e.title}*`,\\n  `>${String(e.summary || '').replace(/\\\\n/g, '\\\\n>')}`,\\n  `*Customer:* ${e.customerName || e.fromName} <${e.fromEmail}>${e.customerCompany ? ' (' + e.customerCompany + ')' : ''}`,\\n  `*Area:* ${e.productArea || 'General'} | *Sentiment:* ${e.sentiment}`,\\n  jiraKey ? `*Jira:* <${jiraUrl}|${jiraKey}>` : `:x: *Jira not created:* ${jiraError.slice(0, 300)}`,\\n  e.link ? `<${e.link}|Open email>` : `_via ${e.source}_`,\\n].join('\\\\n');\\n\\nconst teamsCard = {\\n  type: 'message',\\n  attachments: [{\\n    contentType: 'application/vnd.microsoft.card.adaptive',\\n    content: {\\n      $schema: 'http://adaptivecards.io/schemas/adaptive-card.json', type: 'AdaptiveCard', version: '1.4',\\n      body: [\\n        { type: 'TextBlock', size: 'Medium', weight: 'Bolder', wrap: true,\\n          text: isFollowUp ? `Customer follow-up on ${jiraKey}` : `New customer ${e.category} - ${e.priority}` },\\n        { type: 'TextBlock', wrap: true, weight: 'Bolder', text: e.title },\\n        { type: 'TextBlock', wrap: true, text: e.summary || '' },\\n        { type: 'FactSet', facts: [\\n          { title: 'Customer', value: `${e.customerName || e.fromName} <${e.fromEmail}>` },\\n          { title: 'Area', value: e.productArea || 'General' },\\n          { title: 'Jira', value: jiraKey || 'not created' },\\n        ] },\\n      ],\\n      actions: jiraUrl ? [{ type: 'Action.OpenUrl', title: 'Open in Jira', url: jiraUrl }] : [],\\n    },\\n  }],\\n};\\n\\nreturn { json: { ...e, jiraKey, jiraUrl, jiraError, isFollowUp, slackText, teamsCard } };"}, "typeVersion": 2}, {"id": "db72ab45-3b8a-4154-b029-816854cbd9fc", "name": "Send Slack Notification", "type": "n8n-nodes-base.slack", "onError": "continueRegularOutput", "position": [-1024, 5040], "webhookId": "11133fb4-f759-4a3d-b374-5a1eede4e0a9", "parameters": {"text": "={{ $json.slackText }}", "select": "channel", "channelId": {"__rl": true, "mode": "name", "value": "={{ $json.route.slackChannel }}"}, "otherOptions": {"unfurl_links": false, "includeLinkToWorkflow": false}}, "typeVersion": 2.3}, {"id": "7a947a27-b359-4aa0-a1ff-4aa9fa4317b3", "name": "Check Teams Webhook Availability", "type": "n8n-nodes-base.if", "position": [-816, 5040], "parameters": {"options": {}, "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "loose"}, "combinator": "and", "conditions": [{"id": "d2abfbb7-75e7-4baa-a7a6-f4aff0bfaa4c", "operator": {"type": "boolean", "operation": "true", "singleValue": true}, "leftValue": "={{ !!$('Create Notification Messages').item.json.teamsWebhookUrl }}", "rightValue": ""}]}, "looseTypeValidation": true}, "typeVersion": 2.2}, {"id": "ac0278e4-f7c4-417b-902b-ab77e3f81a75", "name": "Send Teams Notification", "type": "n8n-nodes-base.httpRequest", "onError": "continueRegularOutput", "position": [-560, 4960], "parameters": {"url": "={{ $('Create Notification Messages').item.json.teamsWebhookUrl }}", "method": "POST", "options": {}, "jsonBody": "={{ JSON.stringify($('Create Notification Messages').item.json.teamsCard) }}", "sendBody": true, "specifyBody": "json"}, "typeVersion": 4.2}, {"id": "1c904120-9ce1-48c7-90e9-96ff5559764d", "name": "Return to Main Pipeline", "type": "n8n-nodes-base.code", "position": [-336, 5040], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Result returned to the main pipeline.\\nconst e = $('Create Notification Messages').item.json;\\nconst slack = $('Send Slack Notification').item?.json || {};\\nconst { jiraPayload, teamsCard, slackText, followUpComment, dedupJql, ...rest } = e;\\nreturn { json: {\\n  ...rest,\\n  assignedTo: e.route.owner,\\n  slackChannel: e.route.slackChannel,\\n  slackSent: !slack.error && (!!slack.ok || !!slack.message),\\n  teamsSent: !!e.teamsWebhookUrl,\\n  escalationStatus: !e.jiraKey ? 'Escalation failed - check Jira' : (e.isFollowUp ? 'Follow-up added to ' + e.jiraKey : 'Escalated'),\\n  escalatedAt: new Date().toISOString(),\\n} };"}, "typeVersion": 2}, {"id": "ffaa40e5-cd87-491a-8123-4eec818f6d37", "name": "Build Acknowledgement Reply", "type": "n8n-nodes-base.code", "position": [-2368, 5792], "parameters": {"mode": "runOnceForEachItem", "jsCode": "// Decide whether to acknowledge and build the reply text.\\nconst e = $json;\\nconst mode = String(e.ackMode || 'off').toLowerCase();   // off | draft | send\\nlet skip = '';\\nif (!['draft', 'send'].includes(mode)) skip = 'Acknowledgement disabled';\\nelse if (e.isFollowUp) skip = 'Follow-up on existing ticket';\\nelse if (!e.jiraKey) skip = 'No ticket created';\\nelse if (!e.messageId) skip = 'No message ID';\\n\\nconst RESPONSE_TIME = { Critical: '2 business hours', High: '1 business day', Medium: '2 business days', Low: '3 business days' };\\nconst firstName = String(e.customerName || e.fromName || '').trim().split(/\\\\s+/)[0] || 'there';\\nconst what = { 'Bug': 'bug report', 'Issue': 'support request', 'New Requirement': 'feature request' }[e.category] || 'request';\\nconst company = e.companyName || 'our team';\\n\\nconst ackText = [\\n  `Hi ${firstName},`,\\n  '',\\n  `Thank you for contacting ${company}. We have received your ${what} (reference: ${e.jiraKey}) and passed it to the right team.`,\\n  `You can expect an update within ${RESPONSE_TIME[e.priority] || '2 business days'}. Just reply to this email if you have anything to add.`,\\n  '',\\n  'Kind regards,',\\n  `${company} ${e.ackSignature || ''}`.trim(),\\n].join('\\\\n');\\nconst ackHtml = ackText.split('\\\\n').map(l => `<p style=\\"margin:0\\">${l || '&nbsp;'}</p>`).join('');\\n\\nreturn { json: { ...e, ackMode: mode, ackSkipReason: skip, ackText, ackHtml,\\n  ackRoute: skip ? 'skip' : (e.source === 'Outlook' ? 'outlook' : (mode === 'send' ? 'gmail-send' : 'gmail-draft')) } };"}, "typeVersion": 2}, {"id": "ad1adcf4-d01d-4fd0-8736-5f9878ac6bdd", "name": "Route by Reply Channel", "type": "n8n-nodes-base.switch", "position": [-2144, 5792], "parameters": {"rules": {"values": [{"outputKey": "Gmail send", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "4c142b9f-7a05-4c7a-809a-1e355e7e8705", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.ackRoute }}", "rightValue": "gmail-send"}]}, "renameOutput": true}, {"outputKey": "Gmail draft", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "8f69795d-0bd4-4912-8ad4-e0cb3c35e2d5", "operator": {"type": "string", "operation": "equals"}, "leftValue": "={{ $json.ackRoute }}", "rightValue": "gmail-draft"}]}, "renameOutput": true}, {"outputKey": "Outlook", "conditions": {"options": {"version": 2, "leftValue": "", "caseSensitive": true, "typeValidation": "strict"}, "combinator": "and", "conditions": [{"id": "43f278bf-677b-4573-b2b4-f5da53c450ab", "operator": {"type": "str